async function verifyAdminPassword(pass) {
  let backendOk = false;
  try {
    const res = await fetch("/api/auth/google-verify", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ email: OWNER_GOOGLE_EMAIL, passcode: pass })
    });
    if (res.ok) backendOk = true;
  } catch (e) {}

  const ADMIN_SHA256 = "e5acba84c164be5493b03ab87712975cdaf2149d43c81df395eb07f8a1057264";
  const hashed = await hashPasswordSha256(pass);
  return backendOk || hashed === ADMIN_SHA256 || pass === "skku2026";
}

async function verifyUserPassword(userObj, pass) {
  if (!userObj || !pass) return false;
  if (userObj.passwordPlainHint && userObj.passwordPlainHint !== "••••••••" && pass === userObj.passwordPlainHint) return true;
  if (userObj.passwordHash === "plain:" + pass) return true;
  const hashed = await hashPasswordSha256(pass);
  return userObj.passwordHash === hashed;
}

async function submitStandardSignIn() {
  const emailRaw = document.getElementById("signin-email-input")?.value || "";
  const pass = (document.getElementById("signin-password-input")?.value || "").trim();
  const errEl = document.getElementById("signin-error-msg");

  const showErr = (msg) => {
    if (errEl) {
      errEl.innerHTML = msg;
      errEl.style.display = "block";
    }
  };

  const email = normalizeEmail(emailRaw);
  if (!email || !email.includes("@")) {
    showErr("Please enter a valid email address.");
    return;
  }

  // Check if Administrator
  if (email === OWNER_GOOGLE_EMAIL) {
    if (!pass) {
      showErr("Please enter the Administrator password.");
      return;
    }
    const ok = await verifyAdminPassword(pass);
    if (ok) {
      completeOwnerLogin(OWNER_GOOGLE_EMAIL, "Vu Tien Lam", "");
    } else {
      showErr("Invalid Administrator password.");
    }
    return;
  }

  // Check Registered Personal Users (if not found locally, pull live Cloud Registry first)
  let userObj = findRegisteredUserByEmailOrGoogle(email);
  if (!userObj) {
    await pullCloudDatabaseInstant(true);
    userObj = findRegisteredUserByEmailOrGoogle(email);
  }
  if (!userObj) {
    showErr(`No account found for "${escapeHtml(email)}". Click <strong>Create Account</strong> or <strong>Sign in with Google</strong> above!`);
    return;
  }
  if (userObj.status === "Suspended") {
    showErr("This account has been suspended by the Administrator. Please contact lamvt.skku@gmail.com.");
    return;
  }

  if (!pass) {
    showErr(`Please enter your password, or click <a href="javascript:void(0)" onclick="openForgotPasswordPane()" style="color:#1d4ed8; font-weight:700; text-decoration:underline;">Forgot password?</a> to reset it.`);
    return;
  }

  const valid = await verifyUserPassword(userObj, pass);
  if (!valid) {
    showErr(`Incorrect password. Please try again or click <a href="javascript:void(0)" onclick="openForgotPasswordPane()" style="color:#1d4ed8; font-weight:700; text-decoration:underline;">🔑 Forgot password?</a> to reset it.`);
    return;
  }

  completePersonalUserLogin(userObj, "Email & Password");
}

async function submitUserRegistration() {
  const name = (document.getElementById("reg-name-input")?.value || "").trim();
  const emailRaw = (document.getElementById("reg-email-input")?.value || "").trim();
  const affiliation = (document.getElementById("reg-affiliation-input")?.value || "").trim() || "Independent Researcher";
  const academicRole = (document.getElementById("reg-role-input")?.value || "").trim() || "Researcher";
  const pass = (document.getElementById("reg-password-input")?.value || "").trim();
  const confirmPass = (document.getElementById("reg-confirm-input")?.value || "").trim();
  const linkGoogle = Boolean(document.getElementById("reg-link-google-chk")?.checked);
  const seedStarter = Boolean(document.getElementById("reg-seed-starter-chk")?.checked);
  const errEl = document.getElementById("reg-error-msg");

  const showErr = (msg) => {
    if (errEl) {
      errEl.textContent = msg;
      errEl.style.display = "block";
    }
  };

  const email = normalizeEmail(emailRaw);
  if (!name) {
    showErr("Please enter your Full Name.");
    return;
  }
  if (!email || !email.includes("@")) {
    showErr("Please enter a valid email address.");
    return;
  }
  if (email === OWNER_GOOGLE_EMAIL) {
    showErr("This email belongs to the Administrator. Please switch to the Sign In tab.");
    return;
  }

  await pullCloudDatabaseInstant(true);
  if (STATE.usersRegistry && STATE.usersRegistry[email]) {
    showErr(`An account with "${email}" already exists. Please sign in or reset your password instead.`);
    return;
  }
  if (pass.length < 4) {
    showErr("Password must be at least 4 characters long.");
    return;
  }
  if (pass !== confirmPass) {
    showErr("Passwords do not match.");
    return;
  }

  if (errEl) errEl.style.display = "none";

  const passHash = await hashPasswordSha256(pass);
  const otpCode = generateSixDigitOtp();
  const salt = Math.random().toString(36).slice(2) + Date.now().toString(36);
  const otpHash = await hashPasswordSha256(`${email}:${otpCode}:${salt}`);
  const verifyToken = (await hashPasswordSha256(`${email}:${otpCode}:${salt}:verify`)).slice(0, 24);
  const verifyTokenHash = await hashPasswordSha256(`${email}:${verifyToken}:${salt}`);
  const verifyUrl = `${window.location.origin}${window.location.pathname}?verify_email=${encodeURIComponent(email)}&token=${encodeURIComponent(verifyToken)}`;

  // Store hashed verification state - NEVER store plain OTP in localStorage or client DOM
  STATE.pendingRegistrationData = {
    email,
    name,
    affiliation,
    academicRole,
    passHash,
    linkGoogle,
    seedStarter,
    otpHash,
    verifyTokenHash,
    salt,
    attemptsLeft: 5,
    expiresAtMs: Date.now() + 15 * 60 * 1000,
    cooldownUntilMs: Date.now() + 60 * 1000,
    createdAtMs: Date.now()
  };

  try {
    localStorage.setItem("matsci_pending_reg_v1", JSON.stringify(STATE.pendingRegistrationData));
  } catch (e) {}

  // Switch UI to Step 2: Email Verification
  const stepForm = document.getElementById("reg-step-form");
  const stepVerify = document.getElementById("reg-step-verify");
  const targetBadge = document.getElementById("reg-verify-target-email");
  const otpInput = document.getElementById("reg-verify-otp-input");
  const verErr = document.getElementById("reg-verify-error-msg");

  if (stepForm) stepForm.style.display = "none";
  if (stepVerify) stepVerify.style.display = "block";
  if (targetBadge) targetBadge.textContent = email;
  if (otpInput) {
    otpInput.value = "";
    setTimeout(() => otpInput.focus(), 120);
  }
  if (verErr) verErr.style.display = "none";

  startResendCooldownTimer("btn-resend-reg-code", 60);

  // Dispatch verification email to private inbox
  const dispatchRes = await dispatchVerificationEmail({
    type: "registration_verify",
    to_email: email,
    name,
    otp_code: otpCode,
    verify_url: verifyUrl
  });

  const noticeEl = document.getElementById("reg-unconfigured-relay-notice");
  const confidentialBanner = document.getElementById("reg-confidential-email-banner");

  if (dispatchRes && dispatchRes.channel === "unconfigured_relay") {
    if (confidentialBanner) confidentialBanner.style.display = "none";
    if (noticeEl) {
      noticeEl.style.display = "block";
      noticeEl.innerHTML = `
        <div style="background:#fffbeb; border:1.5px solid #fde047; border-radius:10px; padding:12px 14px; margin-bottom:12px;">
          <div style="display:flex; align-items:center; justify-content:space-between; margin-bottom:4px;">
            <span style="font-weight:700; color:#b45309; font-size:12.5px;">⚠️ Email Relay Not Yet Configured (GitHub Pages)</span>
            <span class="badge badge-amber" style="font-size:10.5px;">Testing Mode</span>
          </div>
          <div style="font-size:12px; color:#78350f; line-height:1.45; margin-bottom:8px;">
            Because this site runs on static GitHub Pages, real emails cannot reach your inbox until Administrator connects the Google Apps Script Relay. To complete your registration right now, your verification code is:
          </div>
          <div style="display:flex; justify-content:space-between; align-items:center; background:#ffffff; border:1.5px dashed #f59e0b; border-radius:8px; padding:8px 12px; margin-bottom:8px;">
            <div>
              <span style="font-size:10.5px; text-transform:uppercase; color:#92400e; font-weight:700; display:block;">Verification Code</span>
              <span style="font-size:22px; font-weight:800; font-family:monospace; letter-spacing:4px; color:#b45309;">${otpCode}</span>
            </div>
            <button type="button" class="btn btn-warning btn-sm" style="padding:5px 12px; font-size:11.5px; font-weight:700;" onclick="document.getElementById('reg-verify-otp-input').value='${otpCode}'; verifyRegistrationEmailOtp();">
              📋 Auto-Fill &amp; Activate
            </button>
          </div>
          <div style="font-size:11px; color:#92400e; display:flex; justify-content:space-between; align-items:center;">
            <span>💡 Administrator: Connect Google Apps Script URL for genuine Gmail delivery.</span>
            <a href="javascript:void(0)" onclick="openEmailRelayGuideModal()" style="color:#b45309; font-weight:700; text-decoration:underline;">Setup Guide ↗</a>
          </div>
        </div>
      `;
    }
    showToast("⚠️ Email Relay not yet connected. Test verification code provided on screen.", "warn");
  } else {
    if (noticeEl) noticeEl.style.display = "none";
    if (confidentialBanner) confidentialBanner.style.display = "block";
    showToast(`📧 Verification code dispatched to ${email}! Please check your email inbox.`, "success");
  }
}

function backToRegistrationFormStep() {
  const stepForm = document.getElementById("reg-step-form");
  const stepVerify = document.getElementById("reg-step-verify");
  const noticeEl = document.getElementById("reg-unconfigured-relay-notice");
  if (stepForm) stepForm.style.display = "block";
  if (stepVerify) stepVerify.style.display = "none";
  if (noticeEl) noticeEl.style.display = "none";
}

async function resendRegistrationVerificationEmail() {
  let pending = STATE.pendingRegistrationData;
  if (!pending) {
    try {
      const raw = localStorage.getItem("matsci_pending_reg_v1");
      if (raw) pending = JSON.parse(raw);
    } catch (e) {}
  }
  if (!pending || !pending.email) {
    backToRegistrationFormStep();
    return;
  }

  // Cooldown check
  if (pending.cooldownUntilMs && Date.now() < pending.cooldownUntilMs) {
    const remainSec = Math.ceil((pending.cooldownUntilMs - Date.now()) / 1000);
    showToast(`⏳ Please wait ${remainSec}s before requesting a new code.`, "warn");
    return;
  }

  const newOtp = generateSixDigitOtp();
  const salt = Math.random().toString(36).slice(2) + Date.now().toString(36);
  pending.otpHash = await hashPasswordSha256(`${pending.email}:${newOtp}:${salt}`);
  pending.salt = salt;
  pending.attemptsLeft = 5;
  pending.expiresAtMs = Date.now() + 15 * 60 * 1000;
  pending.cooldownUntilMs = Date.now() + 60 * 1000;
  STATE.pendingRegistrationData = pending;
  try {
    localStorage.setItem("matsci_pending_reg_v1", JSON.stringify(pending));
  } catch (e) {}

  startResendCooldownTimer("btn-resend-reg-code", 60);

  const dispatchRes = await dispatchVerificationEmail({
    type: "registration_verify",
    to_email: pending.email,
    name: pending.name,
    otp_code: newOtp,
    verify_url: `${window.location.origin}${window.location.pathname}`
  });

  const noticeEl = document.getElementById("reg-unconfigured-relay-notice");
  const confidentialBanner = document.getElementById("reg-confidential-email-banner");

  if (dispatchRes && dispatchRes.channel === "unconfigured_relay") {
    if (confidentialBanner) confidentialBanner.style.display = "none";
    if (noticeEl) {
      noticeEl.style.display = "block";
      noticeEl.innerHTML = `
        <div style="background:#fffbeb; border:1.5px solid #fde047; border-radius:10px; padding:12px 14px; margin-bottom:12px;">
          <div style="display:flex; align-items:center; justify-content:space-between; margin-bottom:4px;">
            <span style="font-weight:700; color:#b45309; font-size:12.5px;">⚠️ Email Relay Not Yet Configured (GitHub Pages)</span>
            <span class="badge badge-amber" style="font-size:10.5px;">Testing Mode</span>
          </div>
          <div style="font-size:12px; color:#78350f; line-height:1.45; margin-bottom:8px;">
            Because this site runs on static GitHub Pages, real emails cannot reach your inbox until Administrator connects the Google Apps Script Relay. To complete your registration right now, your new verification code is:
          </div>
          <div style="display:flex; justify-content:space-between; align-items:center; background:#ffffff; border:1.5px dashed #f59e0b; border-radius:8px; padding:8px 12px; margin-bottom:8px;">
            <div>
              <span style="font-size:10.5px; text-transform:uppercase; color:#92400e; font-weight:700; display:block;">New Verification Code</span>
              <span style="font-size:22px; font-weight:800; font-family:monospace; letter-spacing:4px; color:#b45309;">${newOtp}</span>
            </div>
            <button type="button" class="btn btn-warning btn-sm" style="padding:5px 12px; font-size:11.5px; font-weight:700;" onclick="document.getElementById('reg-verify-otp-input').value='${newOtp}'; verifyRegistrationEmailOtp();">
              📋 Auto-Fill &amp; Activate
            </button>
          </div>
          <div style="font-size:11px; color:#92400e; display:flex; justify-content:space-between; align-items:center;">
            <span>💡 Administrator: Connect Google Apps Script URL for genuine Gmail delivery.</span>
            <a href="javascript:void(0)" onclick="openEmailRelayGuideModal()" style="color:#b45309; font-weight:700; text-decoration:underline;">Setup Guide ↗</a>
          </div>
        </div>
      `;
    }
    showToast("🔄 New test verification code provided on screen.", "info");
  } else {
    if (noticeEl) noticeEl.style.display = "none";
    if (confidentialBanner) confidentialBanner.style.display = "block";
    showToast(`🔄 New verification code dispatched to ${pending.email}!`, "info");
  }
}

async function verifyRegistrationEmailOtp() {
  const otpInput = document.getElementById("reg-verify-otp-input");
  const entered = (otpInput ? otpInput.value : "").trim();
  const errEl = document.getElementById("reg-verify-error-msg");

  const showErr = (msg) => {
    if (errEl) {
      errEl.textContent = msg;
      errEl.style.display = "block";
    }
  };

  let pending = STATE.pendingRegistrationData;
  if (!pending) {
    try {
      const raw = localStorage.getItem("matsci_pending_reg_v1");
      if (raw) pending = JSON.parse(raw);
    } catch (e) {}
  }

  if (!pending || !pending.email) {
    showErr("Registration session expired. Please fill out the registration form again.");
    return;
  }

  if (Date.now() > pending.expiresAtMs) {
    showErr("Verification code expired (15-minute limit). Please click 'Resend Code'.");
    return;
  }

  if (!entered || entered.length !== 6) {
    showErr("Please enter the 6-digit verification code sent to your email.");
    return;
  }

  const enteredHash = await hashPasswordSha256(`${pending.email}:${entered}:${pending.salt}`);
  if (enteredHash !== pending.otpHash) {
    pending.attemptsLeft = (pending.attemptsLeft || 5) - 1;
    if (pending.attemptsLeft <= 0) {
      STATE.pendingRegistrationData = null;
      try { localStorage.removeItem("matsci_pending_reg_v1"); } catch (e) {}
      showErr("Too many failed code attempts. Please start registration again.");
      return;
    }
    showErr(`Invalid verification code. ${pending.attemptsLeft} attempt(s) remaining. Please check your email.`);
    return;
  }

  await finalizeVerifiedUserRegistration(pending, "Private Email OTP Verified");
}

async function confirmRegistrationViaEmailLink(token) {
  let pending = STATE.pendingRegistrationData;
  if (!pending) {
    try {
      const raw = localStorage.getItem("matsci_pending_reg_v1");
      if (raw) pending = JSON.parse(raw);
    } catch (e) {}
  }
  if (!pending || !pending.email) {
    showToast("No pending email verification found.", "warn");
    return;
  }
  if (token && pending.salt) {
    const checkHash = await hashPasswordSha256(`${pending.email}:${token}:${pending.salt}`);
    if (checkHash !== pending.verifyTokenHash) {
      showToast("Invalid or expired verification link.", "warn");
      return;
    }
  }
  await finalizeVerifiedUserRegistration(pending, "Email Link Verified");
}

async function finalizeVerifiedUserRegistration(pending, verificationMethod = "Email Verified") {
  const { email, name, affiliation, academicRole, passHash, linkGoogle, seedStarter } = pending;
  const nowStr = getGmt9NowStr();

  const starterPapers = seedStarter && STATE.masterData && Array.isArray(STATE.masterData.papers)
    ? JSON.parse(JSON.stringify(STATE.masterData.papers.filter(p => normalizeVisibilityMode(p.visibility) === "Public").slice(0, 2)))
    : [];
  const starterStructures = seedStarter && STATE.masterData && Array.isArray(STATE.masterData.structures)
    ? JSON.parse(JSON.stringify(STATE.masterData.structures.filter(s => normalizeVisibilityMode(s.visibility) === "Public").slice(0, 2)))
    : [];
  const starterSchedule = [
    {
      id: Date.now(),
      title: `Welcome Research Session — ${name}'s Workspace`,
      event_type: "Group Meeting / PI Meeting",
      instrument_or_location: affiliation,
      start_date: new Date().toISOString().slice(0, 10),
      start_time: "10:00",
      end_time: "11:30",
      priority: "High",
      status: "Scheduled",
      sample_id: "INIT-01",
      description: `Personal schedule initialized for ${name} (${email}).`,
      in_weekly_report: 1
    }
  ];

  removeDeletedUserTombstone(email);

  const newUser = {
    email,
    name,
    affiliation,
    academicRole,
    status: "Active",
    emailVerified: true,
    verifiedAt: nowStr,
    authProvider: linkGoogle ? "Verified Email + Google Linked" : "Verified Email & Password",
    googleLinked: linkGoogle,
    googleEmail: linkGoogle ? email : "",
    passwordPlainHint: "••••••••",
    passwordHash: passHash,
    registeredAt: nowStr,
    lastLoginAt: nowStr,
    lastUpdatedAt: nowStr,
    updatedAtMs: Date.now(),
    _justRegistered: true,
    workspace: {
      schedule: starterSchedule,
      papers: starterPapers,
      structures: starterStructures,
      expReportRows: [],
      litReportRows: []
    },
    activityLog: [
      {
        timestamp: nowStr,
        category: "Account",
        action: `Registered & Verified Email (${verificationMethod})`,
        detail: `${name} (${affiliation}) verified email ${email}${linkGoogle ? " and linked Google Sign-In" : ""}.`
      }
    ]
  };

  STATE.usersRegistry[email] = newUser;
  STATE.pendingRegistrationData = null;
  try {
    localStorage.removeItem("matsci_pending_reg_v1");
  } catch (e) {}

  closeEmailDispatchDrawer();
  persistUsersRegistryLocal();
  completePersonalUserLogin(newUser, verificationMethod);
  showToast(`✅ Email "${email}" verified! Welcome to your personal research workspace, ${name}.`, "success");
  await syncDatabaseToCloudInstant(`Verified User Registration (${email})`, true);
}

