async function requestPasswordResetEmail(isResend = false) {
  const emailRaw = document.getElementById("reset-email-input")?.value || STATE.pendingPasswordReset?.email || "";
  const errEl = document.getElementById("reset-request-error-msg");

  const showErr = (msg) => {
    if (errEl) {
      errEl.textContent = msg;
      errEl.style.display = "block";
    }
  };

  const email = normalizeEmail(emailRaw);
  if (!email || !email.includes("@")) {
    showErr("Please enter your registered email address.");
    return;
  }

  if (email === OWNER_GOOGLE_EMAIL) {
    showErr("Administrator password recovery is restricted to the system owner (Vu Tien Lam). Please use your Admin security key.");
    return;
  }

  // Rate limiting cooldown check
  if (isResend && STATE.pendingPasswordReset && STATE.pendingPasswordReset.cooldownUntilMs) {
    const remainSec = Math.ceil((STATE.pendingPasswordReset.cooldownUntilMs - Date.now()) / 1000);
    if (remainSec > 0) {
      showToast(`⏳ Please wait ${remainSec}s before requesting a new code.`, "warn");
      return;
    }
  }

  const btn = document.getElementById(isResend ? "btn-resend-reset-code" : "btn-reset-send-code");
  if (btn && !isResend) {
    btn.disabled = true;
    btn.textContent = "Checking Cloud...";
  }

  try {
    let userObj = findRegisteredUserByEmailOrGoogle(email);
    if (!userObj) {
      await pullCloudDatabaseInstant(true);
      userObj = findRegisteredUserByEmailOrGoogle(email);
    }

    if (!userObj) {
      showErr(`No registered account found for "${email}". Please check the spelling or create a new account.`);
      return;
    }

    if (errEl) errEl.style.display = "none";

    const resetCode = generateSixDigitOtp();
    const targetEmail = normalizeEmail(userObj.email);
    const salt = Math.random().toString(36).slice(2) + Date.now().toString(36);
    const resetCodeHash = await hashPasswordSha256(`${targetEmail}:${resetCode}:${salt}`);
    const resetToken = (await hashPasswordSha256(`reset:${targetEmail}:${resetCode}:${salt}`)).slice(0, 24);
    const resetTokenHash = await hashPasswordSha256(`${targetEmail}:${resetToken}:${salt}`);
    const resetUrl = `${window.location.origin}${window.location.pathname}?reset_email=${encodeURIComponent(targetEmail)}&reset_token=${encodeURIComponent(resetToken)}`;

    // Store ONLY salted hash in memory - NEVER expose plain code in DOM or localStorage!
    STATE.pendingPasswordReset = {
      email: targetEmail,
      userName: userObj.name,
      resetCodeHash,
      resetTokenHash,
      salt,
      attemptsLeft: 5,
      expiresAtMs: Date.now() + 15 * 60 * 1000,
      cooldownUntilMs: Date.now() + 60 * 1000,
      createdAtMs: Date.now()
    };

    // Show Step 2 of Reset
    const stepReq = document.getElementById("reset-step-request");
    const stepConf = document.getElementById("reset-step-confirm");
    const badgeEl = document.getElementById("reset-target-email-badge");
    const otpInput = document.getElementById("reset-otp-input");
    const confErr = document.getElementById("reset-confirm-error-msg");

    if (stepReq) stepReq.style.display = "none";
    if (stepConf) stepConf.style.display = "block";
    if (badgeEl) badgeEl.textContent = targetEmail;
    if (confErr) confErr.style.display = "none";
    if (otpInput) {
      otpInput.value = "";
      setTimeout(() => otpInput.focus(), 100);
    }

    startResendCooldownTimer("btn-resend-reset-code", 60);

    // Dispatch the email securely to recipient's private inbox
    const dispatchRes = await dispatchVerificationEmail({
      type: "password_reset",
      to_email: targetEmail,
      name: userObj.name,
      otp_code: resetCode,
      reset_url: resetUrl
    });

    const resetNoticeEl = document.getElementById("reset-unconfigured-relay-notice");
    const resetConfidentialBanner = document.getElementById("reset-confidential-email-banner");

    if (dispatchRes && dispatchRes.channel === "unconfigured_relay") {
      if (resetConfidentialBanner) resetConfidentialBanner.style.display = "none";
      if (resetNoticeEl) {
        resetNoticeEl.style.display = "block";
        resetNoticeEl.innerHTML = `
          <div style="background:#fffbeb; border:1.5px solid #fde047; border-radius:10px; padding:12px 14px; margin-bottom:12px;">
            <div style="display:flex; align-items:center; justify-content:space-between; margin-bottom:4px;">
              <span style="font-weight:700; color:#b45309; font-size:12.5px;">⚠️ Email Relay Not Configured (GitHub Pages)</span>
              <span class="badge badge-amber" style="font-size:10.5px;">Testing Mode</span>
            </div>
            <div style="font-size:12px; color:#78350f; line-height:1.45; margin-bottom:8px;">
              To dispatch real emails to inboxes, Administrator can connect Google Apps Script Relay. For testing, your password reset code is:
            </div>
            <div style="display:flex; justify-content:space-between; align-items:center; background:#ffffff; border:1.5px dashed #f59e0b; border-radius:8px; padding:8px 12px; margin-bottom:8px;">
              <div>
                <span style="font-size:10.5px; text-transform:uppercase; color:#92400e; font-weight:700; display:block;">Password Reset Code</span>
                <span style="font-size:22px; font-weight:800; font-family:monospace; letter-spacing:4px; color:#b45309;">${resetCode}</span>
              </div>
              <button type="button" class="btn btn-warning btn-sm" style="padding:5px 12px; font-size:11.5px; font-weight:700;" onclick="document.getElementById('reset-otp-input').value='${resetCode}';">
                📋 Auto-Fill Code
              </button>
            </div>
            <div style="font-size:11px; color:#92400e; display:flex; justify-content:space-between; align-items:center;">
              <span>💡 Administrator: Connect Google Apps Script URL for genuine Gmail delivery.</span>
              <a href="javascript:void(0)" onclick="openEmailRelayGuideModal()" style="color:#b45309; font-weight:700; text-decoration:underline;">Setup Guide ↗</a>
            </div>
          </div>
        `;
      }
      showToast("⚠️ Email Relay not yet connected. Password reset code provided on screen.", "warn");
    } else {
      if (resetNoticeEl) resetNoticeEl.style.display = "none";
      if (resetConfidentialBanner) resetConfidentialBanner.style.display = "block";
      showToast(
        isResend
          ? `🔄 New 6-digit verification code dispatched to ${targetEmail}!`
          : `📧 Confidential reset code dispatched to ${targetEmail}! Please check your email inbox.`,
        "success"
      );
    }
  } finally {
    if (btn && !isResend) {
      btn.disabled = false;
      btn.textContent = "📧 Send Reset Email →";
    }
  }
}

async function confirmSelfPasswordReset() {
  const otp = (document.getElementById("reset-otp-input")?.value || "").trim();
  const newPass = (document.getElementById("reset-new-password-input")?.value || "").trim();
  const confirmPass = (document.getElementById("reset-confirm-password-input")?.value || "").trim();
  const errEl = document.getElementById("reset-confirm-error-msg");

  const showErr = (msg) => {
    if (errEl) {
      errEl.textContent = msg;
      errEl.style.display = "block";
    }
  };

  let pending = STATE.pendingPasswordReset;
  if (!pending || !pending.email) {
    showErr("Password reset session expired. Please request a new reset code.");
    return;
  }

  if (Date.now() > pending.expiresAtMs) {
    showErr("Verification code has expired (15-minute time limit). Please click 'Resend Code'.");
    return;
  }

  if (!otp || otp.length !== 6) {
    showErr("Please enter the complete 6-digit verification code sent to your email.");
    return;
  }

  const targetEmail = normalizeEmail(pending.email);
  const enteredHash = await hashPasswordSha256(`${targetEmail}:${otp}:${pending.salt}`);

  if (enteredHash !== pending.resetCodeHash) {
    pending.attemptsLeft = (pending.attemptsLeft || 5) - 1;
    if (pending.attemptsLeft <= 0) {
      STATE.pendingPasswordReset = null;
      showErr("Too many failed code attempts. For security, this reset session has been locked. Please request a new code.");
      return;
    }
    showErr(`Invalid 6-digit code. ${pending.attemptsLeft} attempt(s) remaining. Please check your email inbox.`);
    return;
  }

  if (newPass.length < 4) {
    showErr("New password must be at least 4 characters long.");
    return;
  }

  if (newPass !== confirmPass) {
    showErr("New passwords do not match.");
    return;
  }

  const userObj = STATE.usersRegistry[targetEmail] || findRegisteredUserByEmailOrGoogle(targetEmail);
  if (!userObj) {
    showErr("Account not found in registry.");
    return;
  }

  const nowStr = getGmt9NowStr();
  userObj.passwordPlainHint = "••••••••";
  userObj.passwordHash = await hashPasswordSha256(newPass);
  userObj.passwordlessGoogle = false;
  userObj.emailVerified = true;
  userObj.lastUpdatedAt = nowStr;
  userObj.updatedAtMs = Date.now();
  userObj.activityLog = Array.isArray(userObj.activityLog) ? userObj.activityLog : [];
  userObj.activityLog.unshift({
    timestamp: nowStr,
    category: "Security",
    action: "Self-Service Password Reset via Verified Email OTP",
    detail: `User verified email (${targetEmail}) via private 6-digit code and updated password.`
  });

  STATE.usersRegistry[targetEmail] = userObj;
  STATE.pendingPasswordReset = null;
  try {
    localStorage.removeItem("matsci_pending_reset_v1");
  } catch (e) {}

  closeEmailDispatchDrawer();
  persistUsersRegistryLocal();
  completePersonalUserLogin(userObj, "Password Reset & Sign-In");
  showToast("🔑 Password updated successfully! You are now signed in.", "success");
  await syncDatabaseToCloudInstant(`Self Password Reset (${targetEmail})`, true);
}


