let _aeuSelectedGroupsSet = new Set();

function openAdminEditUserModal(email = null, focusPassword = false) {
  if (!requireStrictAdminAuth()) return;
  ensureUserGroupsInitialized();

  const norm = email ? normalizeEmail(email) : "";
  const u = norm ? STATE.usersRegistry[norm] : null;

  const titleEl = document.getElementById("aeu-modal-title");
  const origEmailEl = document.getElementById("aeu-original-email");
  const nameEl = document.getElementById("aeu-name");
  const emailEl = document.getElementById("aeu-email");
  const affilEl = document.getElementById("aeu-affiliation");
  const roleEl = document.getElementById("aeu-role");
  const gLinkedEl = document.getElementById("aeu-google-linked");
  const gEmailEl = document.getElementById("aeu-google-email");
  const statusEl = document.getElementById("aeu-status");
  const curPwEl = document.getElementById("aeu-current-pw-display");
  const newPwEl = document.getElementById("aeu-new-password");
  const delBtn = document.getElementById("aeu-delete-btn");

  if (u) {
    if (titleEl) titleEl.textContent = `✏️ Edit User Profile, Groups & Password — ${u.name}`;
    if (origEmailEl) origEmailEl.value = norm;
    if (nameEl) nameEl.value = u.name || "";
    if (emailEl) emailEl.value = u.email || norm;
    if (affilEl) affilEl.value = u.affiliation || "";
    if (roleEl) roleEl.value = u.academicRole || "Researcher";
    if (gLinkedEl) gLinkedEl.checked = Boolean(u.googleLinked);
    if (gEmailEl) gEmailEl.value = u.googleEmail || (u.googleLinked ? u.email : "");
    if (statusEl) statusEl.value = u.status === "Suspended" ? "Suspended" : "Active";
    if (curPwEl) curPwEl.textContent = (u.passwordPlainHint && u.passwordPlainHint !== "••••••••") ? u.passwordPlainHint : "•••••••• (Encrypted SHA-256)";
    if (newPwEl) {
      newPwEl.value = "";
      newPwEl.placeholder = "Leave blank to keep current password, or type new password...";
    }
    if (delBtn) delBtn.style.display = "inline-flex";

    const memberGroupIds = getGroupsForUserEmail(norm).map(g => g.id);
    _aeuSelectedGroupsSet = new Set(memberGroupIds);
  } else {
    if (titleEl) titleEl.textContent = "➕ Create New Personal User Account (Admin)";
    if (origEmailEl) origEmailEl.value = "";
    if (nameEl) nameEl.value = "";
    if (emailEl) emailEl.value = "";
    if (affilEl) affilEl.value = "Sungkyunkwan University (SKKU)";
    if (roleEl) roleEl.value = "Researcher";
    if (gLinkedEl) gLinkedEl.checked = true;
    if (gEmailEl) gEmailEl.value = "";
    if (statusEl) statusEl.value = "Active";
    if (curPwEl) curPwEl.textContent = "skku1234 (default)";
    if (newPwEl) {
      newPwEl.value = "skku1234";
      newPwEl.placeholder = "Enter initial password for new user...";
    }
    if (delBtn) delBtn.style.display = "none";
    _aeuSelectedGroupsSet = new Set(["grp_skku_lab"]);
  }

  renderAdminEditUserGroupsChecklist();
  document.getElementById("admin-edit-user-modal")?.classList.add("open");

  if (focusPassword && newPwEl) {
    setTimeout(() => newPwEl.focus(), 120);
  } else if (nameEl) {
    setTimeout(() => nameEl.focus(), 120);
  }
}

function renderAdminEditUserGroupsChecklist() {
  const container = document.getElementById("aeu-groups-checklist");
  if (!container) return;
  ensureUserGroupsInitialized();
  const groups = Object.values(STATE.userGroups || {});
  if (groups.length === 0) {
    container.innerHTML = `<span style="font-size:12px; color:#64748b;">No User Groups created yet. Use the box below to create one.</span>`;
    return;
  }

  container.innerHTML = groups.map(g => {
    const checked = _aeuSelectedGroupsSet.has(g.id);
    return `
      <label style="display:inline-flex; align-items:center; gap:6px; padding:5px 10px; border-radius:999px; border:1px solid ${checked ? '#2563eb' : '#cbd5e1'}; background:${checked ? '#eff6ff' : '#ffffff'}; color:${checked ? '#1e3a8a' : '#334155'}; font-size:12px; font-weight:600; cursor:pointer; user-select:none;">
        <input type="checkbox" ${checked ? "checked" : ""} onchange="toggleAeuGroupSelection('${escapeHtml(g.id)}', this.checked)" style="width:14px; height:14px; accent-color:#2563eb;" />
        <span>🏷️ ${escapeHtml(g.name)}</span>
      </label>
    `;
  }).join("");
}

function toggleAeuGroupSelection(gid, checked) {
  if (checked) {
    _aeuSelectedGroupsSet.add(gid);
  } else {
    _aeuSelectedGroupsSet.delete(gid);
  }
  renderAdminEditUserGroupsChecklist();
}

function quickCreateGroupFromUserModal() {
  const input = document.getElementById("aeu-quick-group-name");
  const name = (input ? input.value : "").trim();
  if (!name) {
    showToast("Please enter a name for the new User Group.", "warn");
    return;
  }
  ensureUserGroupsInitialized();
  const slug = name.toLowerCase().replace(/[^a-z0-9]+/g, "_").replace(/^_+|_+$/g, "").slice(0, 24) || "group";
  const gid = `grp_${slug}_${Date.now().toString(36).slice(-4)}`;
  removeDeletedGroupTombstone(gid);
  STATE.userGroups[gid] = {
    id: gid,
    name,
    color: "blue",
    description: `User group created by Administrator`,
    members: [],
    updatedAtMs: Date.now()
  };
  _aeuSelectedGroupsSet.add(gid);
  if (input) input.value = "";
  persistUserGroupsLocal();
  refreshAudienceFilterDropdowns();
  renderAdminEditUserGroupsChecklist();
  showToast(`🏷️ Created group "${name}" and selected it for this user!`, "success");
}

function copyAdminUserCurrentPassword() {
  const curPwEl = document.getElementById("aeu-current-pw-display");
  const pw = (curPwEl ? curPwEl.textContent : "").trim();
  if (!pw || pw === "—") return;
  try {
    navigator.clipboard?.writeText(pw);
    showToast(`📋 Copied password "${pw}" to clipboard!`, "info");
  } catch (e) {}
}

function generateAdminTempPasswordForUser() {
  const chars = "ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz23456789";
  let suffix = "";
  for (let i = 0; i < 4; i++) {
    suffix += chars.charAt(Math.floor(Math.random() * chars.length));
  }
  const tempPass = `skku-${suffix}`;
  const newPwEl = document.getElementById("aeu-new-password");
  if (newPwEl) {
    newPwEl.value = tempPass;
    newPwEl.focus();
    newPwEl.select();
  }
  try { navigator.clipboard?.writeText(tempPass); } catch (e) {}
  showToast(`🎲 Generated temporary password "${tempPass}" (copied to clipboard). Click Save to apply!`, "info");
}

function resetAdminUserPasswordToDefault() {
  const defaultPass = "skku1234";
  const newPwEl = document.getElementById("aeu-new-password");
  if (newPwEl) {
    newPwEl.value = defaultPass;
    newPwEl.focus();
  }
  try { navigator.clipboard?.writeText(defaultPass); } catch (e) {}
  showToast(`🔄 Set password field to "${defaultPass}" (copied to clipboard). Click Save to apply!`, "info");
}

async function saveAdminEditedUser() {
  if (!requireStrictAdminAuth()) return;
  ensureUserGroupsInitialized();

  const origEmail = normalizeEmail(document.getElementById("aeu-original-email")?.value || "");
  const name = (document.getElementById("aeu-name")?.value || "").trim();
  const newEmail = normalizeEmail(document.getElementById("aeu-email")?.value || "");
  const affiliation = (document.getElementById("aeu-affiliation")?.value || "").trim() || "Researcher";
  const academicRole = (document.getElementById("aeu-role")?.value || "").trim() || "Researcher";
  const googleLinked = Boolean(document.getElementById("aeu-google-linked")?.checked);
  const googleEmailRaw = normalizeEmail(document.getElementById("aeu-google-email")?.value || "");
  const status = document.getElementById("aeu-status")?.value || "Active";
  const newPass = (document.getElementById("aeu-new-password")?.value || "").trim();

  if (!name) {
    showToast("Please enter the user's Full Name.", "warn");
    return;
  }
  if (!newEmail || !newEmail.includes("@")) {
    showToast("Please enter a valid Email Address.", "warn");
    return;
  }
  if (newEmail === OWNER_GOOGLE_EMAIL) {
    showToast("Cannot use the Administrator email for a personal user account.", "warn");
    return;
  }
  if (origEmail && newEmail !== origEmail && STATE.usersRegistry[newEmail]) {
    showToast(`Another user account with email "${newEmail}" already exists.`, "warn");
    return;
  }
  if (!origEmail && STATE.usersRegistry[newEmail]) {
    showToast(`A user account with email "${newEmail}" already exists. Editing existing account instead.`, "warn");
  }

  const nowStr = getGmt9NowStr();
  removeDeletedUserTombstone(newEmail);

  let userObj = origEmail ? STATE.usersRegistry[origEmail] : STATE.usersRegistry[newEmail];
  const isNewUser = !userObj;

  if (isNewUser) {
    const initialPass = newPass || "skku1234";
    const passHash = await hashPasswordSha256(initialPass);
    userObj = {
      email: newEmail,
      name,
      affiliation,
      academicRole,
      status,
      authProvider: googleLinked ? "Email + Google Linked" : "Email & Password",
      googleLinked,
      googleEmail: googleLinked ? (googleEmailRaw || newEmail) : "",
      passwordPlainHint: initialPass,
      passwordHash: passHash,
      groups: Array.from(_aeuSelectedGroupsSet),
      registeredAt: nowStr,
      lastLoginAt: nowStr,
      lastUpdatedAt: nowStr,
      updatedAtMs: Date.now(),
      workspace: {
        schedule: [],
        papers: [],
        structures: [],
        expReportRows: [],
        litReportRows: []
      },
      activityLog: [
        {
          timestamp: nowStr,
          category: "Account",
          action: "Created by Administrator",
          detail: `Administrator created personal account for ${name} (${newEmail}).`
        }
      ]
    };
    STATE.usersRegistry[newEmail] = userObj;
  } else {
    // Handle email migration if Administrator changed the user's login email
    if (origEmail && origEmail !== newEmail) {
      addDeletedUserTombstone(origEmail);
      delete STATE.usersRegistry[origEmail];
      STATE.usersRegistry[newEmail] = userObj;
      // Update any group memberships referencing origEmail
      Object.values(STATE.userGroups || {}).forEach(g => {
        if (Array.isArray(g.members)) {
          g.members = g.members.map(m => normalizeEmail(m) === origEmail ? newEmail : normalizeEmail(m));
        }
      });
      if (STATE.selectedInspectorUserEmail === origEmail) {
        STATE.selectedInspectorUserEmail = newEmail;
      }
      if (STATE.adminPreviewUserEmail === origEmail) {
        STATE.adminPreviewUserEmail = newEmail;
      }
    }

    userObj.email = newEmail;
    userObj.name = name;
    userObj.affiliation = affiliation;
    userObj.academicRole = academicRole;
    userObj.status = status;
    userObj.googleLinked = googleLinked;
    userObj.googleEmail = googleLinked ? (googleEmailRaw || newEmail) : "";
    userObj.authProvider = googleLinked ? "Email + Google Linked" : "Email & Password";
    userObj.lastUpdatedAt = nowStr;
    userObj.updatedAtMs = Date.now();
    userObj.activityLog = userObj.activityLog || [];

    if (newPass) {
      if (newPass.length < 4) {
        showToast("New password must be at least 4 characters long.", "warn");
        return;
      }
      userObj.passwordPlainHint = newPass;
      userObj.passwordHash = await hashPasswordSha256(newPass);
      userObj.activityLog.unshift({
        timestamp: nowStr,
        category: "Security",
        action: "Password Changed / Reset by Administrator",
        detail: `Administrator updated password & profile for ${name} (${newEmail}).`
      });
    } else {
      userObj.activityLog.unshift({
        timestamp: nowStr,
        category: "Profile",
        action: "Profile & Groups Updated by Administrator",
        detail: `Updated profile (${affiliation} — ${academicRole}) and group assignments.`
      });
    }
  }

  // Update group memberships for this user across all groups
  Object.values(STATE.userGroups || {}).forEach(g => {
    g.members = Array.isArray(g.members) ? g.members.map(normalizeEmail) : [];
    const shouldBeMember = _aeuSelectedGroupsSet.has(g.id);
    const idx = g.members.indexOf(newEmail);
    if (shouldBeMember && idx === -1) {
      g.members.push(newEmail);
      g.updatedAtMs = Date.now();
    } else if (!shouldBeMember && idx !== -1) {
      g.members.splice(idx, 1);
      g.updatedAtMs = Date.now();
    }
  });
  userObj.groups = Array.from(_aeuSelectedGroupsSet);

  syncUserAndGroupMemberships();
  persistUsersRegistryLocal();
  persistUserGroupsLocal();
  saveStaticDb({ skipCloudPush: true });

  STATE.selectedInspectorUserEmail = newEmail;
  closeModal("admin-edit-user-modal");
  applyActiveWorkspaceData();
  refreshAllWorkspaceViews();
  renderAdminUsersDirectory();

  showToast(`✅ Saved user profile${newPass ? " & new password" : ""} for ${name} (${newEmail})!`, "success");
  await syncDatabaseToCloudInstant(`Admin updated user (${newEmail})`, true);
}

async function deleteUserFromEditModal() {
  const origEmail = normalizeEmail(document.getElementById("aeu-original-email")?.value || "");
  if (!origEmail) return;
  closeModal("admin-edit-user-modal");
  await deleteUserAccountByAdmin(origEmail);
}

// ============================================================================
// Admin User Groups Management Modal (#admin-groups-modal)
// ============================================================================

let _agmSelectedMembersSet = new Set();

function openAdminGroupsModal(selectGroupId = null) {
  if (!requireStrictAdminAuth()) return;
  ensureUserGroupsInitialized();

  const groupIds = Object.keys(STATE.userGroups || {});
  if (selectGroupId && STATE.userGroups[selectGroupId]) {
    STATE.selectedAdminGroupId = selectGroupId;
  } else if (!STATE.selectedAdminGroupId || !STATE.userGroups[STATE.selectedAdminGroupId]) {
    STATE.selectedAdminGroupId = groupIds[0] || null;
  }

  renderAdminGroupsModalList();
  if (STATE.selectedAdminGroupId && STATE.userGroups[STATE.selectedAdminGroupId]) {
    selectGroupInAdminModal(STATE.selectedAdminGroupId);
  } else {
    startNewUserGroupInModal();
  }

  document.getElementById("admin-groups-modal")?.classList.add("open");
}

function countItemsSharedWithGroup(gid) {
  const token = `group:${gid}`;
  const checkItem = (item) => {
    if (!item) return false;
    const vis = normalizeVisibilityMode(item.visibility);
    if (vis !== "Groups" && vis !== "Specific") return false;
    const allowedUsers = Array.isArray(item.allowed_users) ? item.allowed_users : [];
    const allowedGroups = Array.isArray(item.allowed_groups) ? item.allowed_groups : [];
    return allowedGroups.includes(gid) || allowedUsers.includes(token);
  };
  const papers = ((STATE.masterData && STATE.masterData.papers) || STATE.papers || []).filter(checkItem).length;
  const structures = ((STATE.masterData && STATE.masterData.structures) || STATE.structures || []).filter(checkItem).length;
  const schedule = ((STATE.masterData && STATE.masterData.schedule) || STATE.schedule || []).filter(checkItem).length;
  return { papers, structures, schedule, total: papers + structures + schedule };
}

function renderAdminGroupsModalList() {
  ensureUserGroupsInitialized();
  const listEl = document.getElementById("admin-groups-list-panel");
  const totalBadge = document.getElementById("agm-total-groups-badge");
  const groups = Object.values(STATE.userGroups || {});

  if (totalBadge) {
    totalBadge.textContent = `${groups.length} group${groups.length === 1 ? "" : "s"}`;
  }
  if (!listEl) return;

  if (groups.length === 0) {
    listEl.innerHTML = `<div style="padding:20px; text-align:center; color:#64748b; font-size:12.5px;">No user groups configured yet. Click "+ Create New Group" above.</div>`;
    return;
  }

  listEl.innerHTML = groups.map(g => {
    const isAct = STATE.selectedAdminGroupId === g.id;
    const mCount = Array.isArray(g.members) ? g.members.length : 0;
    const shared = countItemsSharedWithGroup(g.id);
    const badgeClass = `badge-${g.color || "blue"}`;
    return `
      <div class="admin-user-card ${isAct ? "active" : ""}" onclick="selectGroupInAdminModal('${escapeHtml(g.id)}')">
        <div style="display:flex; justify-content:space-between; align-items:center; gap:6px;">
          <span class="badge ${badgeClass}" style="font-size:11.5px;">🏷️ ${escapeHtml(g.name)}</span>
          <span style="font-size:11px; font-weight:700; color:#475569;">👥 ${mCount} member${mCount === 1 ? "" : "s"}</span>
        </div>
        <div style="font-size:11.5px; color:#64748b; margin-top:5px;">
          ${escapeHtml(g.description || "No description")}
        </div>
        <div style="display:flex; justify-content:space-between; align-items:center; margin-top:6px; padding-top:5px; border-top:1px dashed #e2e8f0; font-size:10.5px; color:#1e40af;">
          <span>🔒 Shared items: <strong>${shared.total}</strong> (${shared.papers}P, ${shared.structures}S, ${shared.schedule}E)</span>
          <span style="font-family:monospace; color:#94a3b8;">${escapeHtml(g.id)}</span>
        </div>
      </div>
    `;
  }).join("");
}

function selectGroupInAdminModal(gid) {
  ensureUserGroupsInitialized();
  const g = STATE.userGroups[gid];
  if (!g) return;
  STATE.selectedAdminGroupId = gid;

  const titleEl = document.getElementById("agm-editor-title");
  const idEl = document.getElementById("agm-id");
  const nameEl = document.getElementById("agm-name");
  const colorEl = document.getElementById("agm-color");
  const descEl = document.getElementById("agm-desc");
  const delBtn = document.getElementById("agm-delete-btn");
  const shortcutEl = document.getElementById("agm-group-filter-shortcut");

  if (titleEl) titleEl.textContent = `🏷️ Edit User Group — ${g.name}`;
  if (idEl) idEl.value = g.id;
  if (nameEl) nameEl.value = g.name || "";
  if (colorEl) colorEl.value = g.color || "blue";
  if (descEl) descEl.value = g.description || "";
  if (delBtn) delBtn.style.display = "inline-flex";
  if (shortcutEl) {
    shortcutEl.innerHTML = `
      <button type="button" class="btn btn-outline btn-sm" style="padding:3px 9px; font-size:11px;" onclick="filterWebsiteByUserGroup('${escapeHtml(g.id)}', 'GROUP_VIEW')">
        👁️ Preview Content Viewable by Group
      </button>
    `;
  }

  _agmSelectedMembersSet = new Set((g.members || []).map(normalizeEmail));
  renderAdminGroupsModalList();
  renderAdminGroupMembersChecklist();
  renderGroupSharedStatsBox(g.id);
}

function startNewUserGroupInModal() {
  STATE.selectedAdminGroupId = null;
  const titleEl = document.getElementById("agm-editor-title");
  const idEl = document.getElementById("agm-id");
  const nameEl = document.getElementById("agm-name");
  const colorEl = document.getElementById("agm-color");
  const descEl = document.getElementById("agm-desc");
  const delBtn = document.getElementById("agm-delete-btn");
  const shortcutEl = document.getElementById("agm-group-filter-shortcut");
  const statsBox = document.getElementById("agm-shared-stats-box");

  if (titleEl) titleEl.textContent = "➕ Create New User Group";
  if (idEl) idEl.value = "";
  if (nameEl) {
    nameEl.value = "";
    setTimeout(() => nameEl.focus(), 100);
  }
  if (colorEl) colorEl.value = "blue";
  if (descEl) descEl.value = "";
  if (delBtn) delBtn.style.display = "none";
  if (shortcutEl) shortcutEl.innerHTML = "";
  if (statsBox) {
    statsBox.innerHTML = `💡 Fill in the group name and select members above, then click <strong>"💾 Save User Group"</strong>. Once saved, you can target this group in any Visibility dropdown or filter the website by this group.`;
  }

  _agmSelectedMembersSet = new Set();
  renderAdminGroupsModalList();
  renderAdminGroupMembersChecklist();
}

function renderAdminGroupMembersChecklist() {
  const container = document.getElementById("agm-members-checklist");
  const countLabel = document.getElementById("agm-member-count-label");
  const query = (document.getElementById("agm-member-search")?.value || "").toLowerCase().trim();

  if (countLabel) {
    countLabel.textContent = `${_agmSelectedMembersSet.size} selected`;
  }
  if (!container) return;

  const users = Object.values(STATE.usersRegistry || {});
  const filtered = users.filter(u => {
    if (!query) return true;
    const hay = `${u.name} ${u.email} ${u.affiliation} ${u.academicRole}`.toLowerCase();
    return hay.includes(query);
  });

  if (filtered.length === 0) {
    container.innerHTML = `<div style="padding:12px; text-align:center; color:#64748b; font-size:12px;">No matching users found.</div>`;
    return;
  }

  container.innerHTML = filtered.map(u => {
    const normEmail = normalizeEmail(u.email);
    const checked = _agmSelectedMembersSet.has(normEmail);
    return `
      <label style="display:flex; justify-content:space-between; align-items:center; padding:6px 10px; border-radius:7px; border:1px solid ${checked ? '#3b82f6' : '#e2e8f0'}; background:${checked ? '#eff6ff' : '#ffffff'}; cursor:pointer; font-size:12.5px;">
        <div style="display:flex; align-items:center; gap:8px;">
          <input type="checkbox" ${checked ? "checked" : ""} onchange="toggleGroupMemberInModal('${escapeHtml(normEmail)}', this.checked)" style="width:15px; height:15px; accent-color:#2563eb;" />
          <div>
            <strong style="color:#0f172a;">👤 ${escapeHtml(u.name)}</strong>
            <span style="font-family:monospace; color:#2563eb; font-size:11.5px; margin-left:6px;">${escapeHtml(u.email)}</span>
            <div style="font-size:11px; color:#64748b;">${escapeHtml(u.affiliation || "Researcher")} (${escapeHtml(u.academicRole || "Member")})</div>
          </div>
        </div>
        ${checked ? `<span class="badge badge-blue" style="font-size:10px;">Member</span>` : ""}
      </label>
    `;
  }).join("");
}

function toggleGroupMemberInModal(email, checked) {
  const norm = normalizeEmail(email);
  if (checked) {
    _agmSelectedMembersSet.add(norm);
  } else {
    _agmSelectedMembersSet.delete(norm);
  }
  renderAdminGroupMembersChecklist();
}

function toggleAllGroupModalMembers(selectAll) {
  const users = Object.values(STATE.usersRegistry || {});
  if (selectAll) {
    users.forEach(u => _agmSelectedMembersSet.add(normalizeEmail(u.email)));
  } else {
    _agmSelectedMembersSet.clear();
  }
  renderAdminGroupMembersChecklist();
}

function renderGroupSharedStatsBox(gid) {
  const box = document.getElementById("agm-shared-stats-box");
  if (!box || !gid || !STATE.userGroups[gid]) return;
  const g = STATE.userGroups[gid];
  const stats = countItemsSharedWithGroup(gid);
  box.innerHTML = `
    <div style="display:flex; justify-content:space-between; align-items:center; flex-wrap:wrap; gap:8px;">
      <div>
        <strong>🔒 Content Targeted to "${escapeHtml(g.name)}":</strong>
        <span style="margin-left:6px;">📚 <strong>${stats.papers}</strong> Papers &nbsp;|&nbsp; 💎 <strong>${stats.structures}</strong> Structures &nbsp;|&nbsp; 📅 <strong>${stats.schedule}</strong> Events</span>
      </div>
      <div style="display:flex; gap:6px; flex-wrap:wrap;">
        <button type="button" class="btn btn-outline btn-sm" style="padding:3px 8px; font-size:11px; background:#fff;" onclick="filterWebsiteByUserGroup('${escapeHtml(gid)}', 'GROUP_ASSIGNED')">
          🎯 Filter Assigned Items
        </button>
        <button type="button" class="btn btn-outline btn-sm" style="padding:3px 8px; font-size:11px; background:#fff;" onclick="filterWebsiteByUserGroup('${escapeHtml(gid)}', 'GROUP_VIEW')">
          👁️ Filter All Viewable by Group
        </button>
      </div>
    </div>
  `;
}

async function saveUserGroupFromModal() {
  if (!requireStrictAdminAuth()) return;
  ensureUserGroupsInitialized();

  let gid = (document.getElementById("agm-id")?.value || "").trim();
  const name = (document.getElementById("agm-name")?.value || "").trim();
  const color = document.getElementById("agm-color")?.value || "blue";
  const description = (document.getElementById("agm-desc")?.value || "").trim();

  if (!name) {
    showToast("Please enter a Group Name.", "warn");
    return;
  }

  if (!gid) {
    const slug = name.toLowerCase().replace(/[^a-z0-9]+/g, "_").replace(/^_+|_+$/g, "").slice(0, 24) || "group";
    gid = `grp_${slug}_${Date.now().toString(36).slice(-4)}`;
  }

  removeDeletedGroupTombstone(gid);
  STATE.userGroups[gid] = {
    id: gid,
    name,
    color,
    description,
    members: Array.from(_agmSelectedMembersSet),
    updatedAtMs: Date.now()
  };

  // Sync each user's .groups array with group memberships
  Object.values(STATE.usersRegistry || {}).forEach(u => {
    const normEmail = normalizeEmail(u.email);
    u.groups = Array.isArray(u.groups) ? u.groups : [];
    const hasGid = u.groups.includes(gid);
    const shouldHave = _agmSelectedMembersSet.has(normEmail);
    if (shouldHave && !hasGid) {
      u.groups.push(gid);
    } else if (!shouldHave && hasGid) {
      u.groups = u.groups.filter(x => x !== gid);
    }
  });

  syncUserAndGroupMemberships();
  persistUserGroupsLocal();
  persistUsersRegistryLocal();
  saveStaticDb({ skipCloudPush: true });

  STATE.selectedAdminGroupId = gid;
  refreshAudienceFilterDropdowns();
  renderAdminGroupsModalList();
  selectGroupInAdminModal(gid);
  renderAdminUsersDirectory();
  renderDashboardAdminUsersSummary();

  showToast(`🏷️ Saved User Group "${name}" (${_agmSelectedMembersSet.size} members)!`, "success");
  await syncDatabaseToCloudInstant(`Saved User Group (${name})`, true);
}

async function deleteCurrentGroupFromModal() {
  if (!requireStrictAdminAuth()) return;
  const gid = (document.getElementById("agm-id")?.value || "").trim();
  if (!gid || !STATE.userGroups[gid]) return;
  const g = STATE.userGroups[gid];

  const ok = await confirmAction(
    "Are you sure you want to delete this User Group? Users in this group will not be deleted, only the group tag itself.",
    `Group: ${g.name} (${(g.members || []).length} members)`
  );
  if (!ok) return;

  addDeletedGroupTombstone(gid);
  delete STATE.userGroups[gid];

  Object.values(STATE.usersRegistry || {}).forEach(u => {
    if (Array.isArray(u.groups)) {
      u.groups = u.groups.filter(x => x !== gid);
    }
  });

  syncUserAndGroupMemberships();
  persistUserGroupsLocal();
  persistUsersRegistryLocal();
  saveStaticDb({ skipCloudPush: true });

  const remainingIds = Object.keys(STATE.userGroups || {});
  STATE.selectedAdminGroupId = remainingIds[0] || null;
  refreshAudienceFilterDropdowns();
  renderAdminGroupsModalList();
  if (STATE.selectedAdminGroupId) {
    selectGroupInAdminModal(STATE.selectedAdminGroupId);
  } else {
    startNewUserGroupInModal();
  }
  renderAdminUsersDirectory();
  renderDashboardAdminUsersSummary();

  showToast(`Deleted User Group "${g.name}".`, "info");
  await syncDatabaseToCloudInstant(`Deleted User Group (${g.name})`, true);
}

function startAdminUserPreview(email) {
  if (!requireStrictAdminAuth()) return;
  const norm = normalizeEmail(email);
  const u = STATE.usersRegistry[norm];
  if (!u) return;

  STATE.adminPreviewUserEmail = norm;
  applyActiveWorkspaceData();
  refreshAllWorkspaceViews();
  autofillReportFromDatabase(true);
  closeModal("admin-users-modal");
  showToast(`👁️ Now inspecting ${u.name}'s live workspace (${u.email}). Click "Return to Administrator Master Workspace" in the top banner when finished.`, "info");
}

function exitAdminUserPreview() {
  STATE.adminPreviewUserEmail = null;
  applyActiveWorkspaceData();
  refreshAllWorkspaceViews();
  autofillReportFromDatabase(true);
  showToast("Returned to Administrator Master Workspace.", "success");
}

async function deleteUserAccountByAdmin(email) {
  if (!requireStrictAdminAuth()) return;
  const norm = normalizeEmail(email);
  const u = STATE.usersRegistry[norm];
  if (!u) return;

  const ok = await confirmAction(
    "Are you sure you want to permanently delete this personal user account and all of its workspace data?",
    `${u.name} (${u.email}) — ${u.affiliation || "Researcher"}`
  );
  if (!ok) return;

  const delTime = Date.now();
  addDeletedUserTombstone(norm, delTime);
  delete STATE.usersRegistry[norm];
  Object.values(STATE.userGroups || {}).forEach(g => {
    if (Array.isArray(g.members)) {
      g.members = g.members.filter(m => normalizeEmail(m) !== norm);
    }
  });
  if (STATE.adminPreviewUserEmail === norm) {
    STATE.adminPreviewUserEmail = null;
  }
  if (STATE.selectedInspectorUserEmail === norm) {
    STATE.selectedInspectorUserEmail = Object.keys(STATE.usersRegistry)[0] || null;
  }
  persistUsersRegistryLocal();
  persistUserGroupsLocal();
  saveStaticDb({ skipCloudPush: true });
  applyActiveWorkspaceData();
  refreshAllWorkspaceViews();
  renderAdminUsersDirectory();
  renderDashboardAdminUsersSummary();
  showToast(`Deleting user account ${u.email} and syncing to Cloud...`, "info");
  await syncDatabaseToCloudInstant(`Deleted user account (${norm})`, false);
  showToast(`🗑️ Permanently deleted user account ${u.email} from Cloud and local database.`, "success");
}

// ============================================================================
// Interactive Monthly Calendar & Google Calendar Synchronization
// ============================================================================

const MONTH_NAMES = [
  "January", "February", "March", "April", "May", "June",
  "July", "August", "September", "October", "November", "December"
];
const SHORT_MONTH_NAMES = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
const WEEKDAY_NAMES_SHORT = ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"];
const WEEKDAY_NAMES_FULL = ["Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"];

function getKstTodayIso() {
  try {
    return new Intl.DateTimeFormat("en-CA", { timeZone: "Asia/Seoul", year: "numeric", month: "2-digit", day: "2-digit" }).format(new Date());
  } catch (e) {
    return new Date().toISOString().split("T")[0];
  }
}

function getKstCurrentMinutes() {
  try {
    const parts = new Intl.DateTimeFormat("en-GB", {
      timeZone: "Asia/Seoul", hour: "2-digit", minute: "2-digit", hour12: false
    }).formatToParts(new Date());
    const h = parseInt(parts.find(p => p.type === "hour")?.value || "0", 10);
    const m = parseInt(parts.find(p => p.type === "minute")?.value || "0", 10);
    return h * 60 + m;
  } catch (e) {
    const d = new Date();
    return d.getHours() * 60 + d.getMinutes();
  }
}

function parseIsoDateLocal(iso) {
  const m = String(iso || "").match(/^(\d{4})-(\d{2})-(\d{2})$/);
  if (!m) return new Date();
  return new Date(parseInt(m[1], 10), parseInt(m[2], 10) - 1, parseInt(m[3], 10));
}

function formatIsoDateLocal(d) {
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`;
}

function getCalendarFocusDateIso() {
  if (!STATE.calendarFocusDate) {
    const todayIso = getKstTodayIso();
    const tParts = parseIsoDateLocal(todayIso);
    if (STATE.calendarYear === tParts.getFullYear() && STATE.calendarMonth === tParts.getMonth()) {
      STATE.calendarFocusDate = todayIso;
    } else {
      STATE.calendarFocusDate = `${STATE.calendarYear}-${String(STATE.calendarMonth + 1).padStart(2, "0")}-01`;
    }
  }
  return STATE.calendarFocusDate;
}

function setCalendarFocusDateIso(iso) {
  const d = parseIsoDateLocal(iso);
  STATE.calendarFocusDate = formatIsoDateLocal(d);
  STATE.calendarYear = d.getFullYear();
  STATE.calendarMonth = d.getMonth();
}

function getCalendarViewMode() {
  if (!STATE.calendarViewMode) {
    try {
      const saved = localStorage.getItem("matsci_cal_view_mode");
      STATE.calendarViewMode = ["month", "week", "day", "agenda"].includes(saved) ? saved : "month";
    } catch (e) {
      STATE.calendarViewMode = "month";
    }
  }
  return STATE.calendarViewMode;
}

function setCalendarViewMode(mode) {
  if (!["month", "week", "day", "agenda"].includes(mode)) mode = "month";
  STATE.calendarViewMode = mode;
  try { localStorage.setItem("matsci_cal_view_mode", mode); } catch (e) {}
  renderMonthlyCalendar();
}
window.setCalendarViewMode = setCalendarViewMode;

function navigateCalendar(delta) {
  const mode = getCalendarViewMode();
  const focus = parseIsoDateLocal(getCalendarFocusDateIso());
  if (mode === "week") {
    focus.setDate(focus.getDate() + delta * 7);
    setCalendarFocusDateIso(formatIsoDateLocal(focus));
  } else if (mode === "day") {
    focus.setDate(focus.getDate() + delta);
    setCalendarFocusDateIso(formatIsoDateLocal(focus));
  } else {
    // Month or Agenda: step by 1 month
    let m = STATE.calendarMonth + delta;
    let y = STATE.calendarYear;
    if (m < 0) { m = 11; y -= 1; }
    else if (m > 11) { m = 0; y += 1; }
    STATE.calendarYear = y;
    STATE.calendarMonth = m;
    STATE.calendarFocusDate = `${y}-${String(m + 1).padStart(2, "0")}-01`;
  }
  renderMonthlyCalendar();
}
window.navigateCalendar = navigateCalendar;

function changeCalendarMonth(delta) {
  navigateCalendar(delta);
}
window.changeCalendarMonth = changeCalendarMonth;

function resetCalendarToday() {
  setCalendarFocusDateIso(getKstTodayIso());
  renderMonthlyCalendar();
}
window.resetCalendarToday = resetCalendarToday;

function jumpCalendarToDay(isoDate, keepMode = false) {
  setCalendarFocusDateIso(isoDate);
  if (!keepMode) {
    STATE.calendarViewMode = "day";
    try { localStorage.setItem("matsci_cal_view_mode", "day"); } catch (e) {}
  }
  renderMonthlyCalendar();
}
window.jumpCalendarToDay = jumpCalendarToDay;

function toggleCalendarLegendCategory(catVal) {
  const sel = document.getElementById("cal-category-filter");
  if (!sel) return;
  sel.value = (sel.value === catVal) ? "ALL" : catVal;
  renderMonthlyCalendar();
}
window.toggleCalendarLegendCategory = toggleCalendarLegendCategory;

function getCalendarEventColorClass(ev) {
  const isGoogle = Boolean(ev.syncedWithGoogle || ev.googleEventId || (ev.event_type || "").includes("Google Calendar"));
  if (isGoogle) return { cls: "cat-gcal", dot: "#0369a1" };
  const t = String(ev.event_type || "").toLowerCase();
  if (t.includes("synthesis") || t.includes("furnace")) return { cls: "cat-synth", dot: "#d97706" };
  if (t.includes("characterization") || t.includes("xrd") || t.includes("sem")) return { cls: "cat-char", dot: "#2f6f5e" };
  if (t.includes("meeting") || t.includes("pi")) return { cls: "cat-meet", dot: "#9a3412" };
  if (t.includes("electrochem")) return { cls: "cat-elec", dot: "#7c5a2b" };
  if (t.includes("data") || t.includes("manuscript") || t.includes("writing")) return { cls: "cat-data", dot: "#4f5d75" };
  return { cls: "cat-custom", dot: "#7c3f58" };
}

function parseTimeToMinutes(timeStr, fallbackMin = 540) {
  const m = String(timeStr || "").match(/^(\d{1,2}):(\d{2})/);
  if (!m) return fallbackMin;
  return Math.min(24 * 60, Math.max(0, parseInt(m[1], 10) * 60 + parseInt(m[2], 10)));
}

function getCalendarFilteredEvents() {
  const q = (document.getElementById("cal-search-input")?.value || "").toLowerCase().trim();
  const catFilter = document.getElementById("cal-category-filter")?.value || "ALL";
  const statusFilter = document.getElementById("cal-status-filter")?.value || "ALL";

  return (STATE.schedule || []).filter(ev => {
    if (catFilter !== "ALL") {
      if (catFilter === "__GCAL__") {
        const isG = Boolean(ev.syncedWithGoogle || ev.googleEventId || (ev.event_type || "").includes("Google Calendar"));
        if (!isG) return false;
      } else if ((ev.event_type || "") !== catFilter) {
        return false;
      }
    }
    if (statusFilter !== "ALL" && (ev.status || "Scheduled") !== statusFilter) return false;
    if (q) {
      const partText = typeof formatEventParticipantsSummary === "function" ? formatEventParticipantsSummary(ev) : "";
      const hay = `${ev.title || ""} ${ev.event_type || ""} ${ev.instrument_or_location || ""} ${ev.description || ""} ${partText}`.toLowerCase();
      if (!hay.includes(q)) return false;
    }
    return true;
  });
}

function buildEventsByDateMap(eventsList) {
  const eventsByDate = {};
  (eventsList || []).forEach(item => {
    const sDate = item.start_date;
    if (!sDate) return;
    const eDate = item.end_date || item.start_date;
    const range = getDatesInRange(sDate, eDate);
    const totalDays = range.length;
    const isMulti = totalDays > 1;

    range.forEach((d, dayIndex) => {
      if (!eventsByDate[d]) eventsByDate[d] = [];
      eventsByDate[d].push({
        ...item,
        isMultiDay: isMulti,
        dayIndex: dayIndex + 1,
        totalDays,
        isFirstDay: dayIndex === 0,
        isLastDay: dayIndex === totalDays - 1
      });
    });
  });
  Object.values(eventsByDate).forEach(arr => {
    arr.sort((a, b) => {
      if (a.isMultiDay !== b.isMultiDay) return a.isMultiDay ? -1 : 1;
      return parseTimeToMinutes(a.start_time) - parseTimeToMinutes(b.start_time);
    });
  });
  return eventsByDate;
}

function renderMonthlyCalendar() {
  const stage = document.getElementById("calendar-view-stage");
  const titleEl = document.getElementById("cal-month-title");
  if (!stage || !titleEl) return;

  const mode = getCalendarViewMode();
  const todayIso = getKstTodayIso();
  const focusIso = getCalendarFocusDateIso();
  const focusDate = parseIsoDateLocal(focusIso);

  // Sync mode segmented buttons
  ["month", "week", "day", "agenda"].forEach(m => {
    const btn = document.getElementById(`btn-cal-mode-${m}`);
    if (btn) btn.classList.toggle("active", m === mode);
  });

  // Sync Category Filter dropdown with Admin-configured Event Categories
  const catSel = document.getElementById("cal-category-filter");
  const activeCat = catSel ? (catSel.value || "ALL") : "ALL";
  const allCats = typeof getEventCategoriesList === "function" ? getEventCategoriesList() : [];
  if (catSel) {
    let opts = `<option value="ALL">All Categories</option>`;
    allCats.forEach(c => {
      opts += `<option value="${escapeHtml(c)}"${activeCat === c ? " selected" : ""}>${escapeHtml(c)}</option>`;
    });
    opts += `<option value="__GCAL__"${activeCat === "__GCAL__" ? " selected" : ""}>Google Calendar</option>`;
    catSel.innerHTML = opts;
  }

  // Render dynamic clickable Category Legend
  const legendBar = document.getElementById("cal-legend-items");
  const countBadge = document.getElementById("cal-active-count-label");
  const filteredEvents = getCalendarFilteredEvents();
  const eventsByDate = buildEventsByDateMap(filteredEvents);

  if (legendBar) {
    legendBar.innerHTML = allCats.map(c => {
      const col = getCalendarEventColorClass({ event_type: c });
      const safeC = escapeHtml(c).replace(/'/g, "\\'");
      return `<button type="button" class="cal-legend-dot-btn ${activeCat === c ? "active" : ""}" onclick="toggleCalendarLegendCategory('${safeC}')"><span class="cal-legend-dot" style="background:${col.dot};"></span>${escapeHtml(c)}</button>`;
    }).join("") + `<button type="button" class="cal-legend-dot-btn ${activeCat === "__GCAL__" ? "active" : ""}" onclick="toggleCalendarLegendCategory('__GCAL__')"><span class="cal-legend-dot" style="background:#0369a1;"></span>Google Calendar</button>`;
  }

  if (mode === "month") {
    _renderCalendarMonthView(stage, titleEl, countBadge, eventsByDate, todayIso);
  } else if (mode === "week") {
    _renderCalendarWeekView(stage, titleEl, countBadge, focusDate, eventsByDate, todayIso);
  } else if (mode === "day") {
    _renderCalendarDayView(stage, titleEl, countBadge, focusDate, focusIso, eventsByDate, todayIso);
  } else {
    _renderCalendarAgendaView(stage, titleEl, countBadge, eventsByDate, todayIso);
  }
}

function _renderCalendarMonthView(stage, titleEl, countBadge, eventsByDate, todayIso) {
  const year = STATE.calendarYear;
  const month = STATE.calendarMonth;
  titleEl.textContent = `${MONTH_NAMES[month]} ${year}`;

  const firstDay = new Date(year, month, 1).getDay();
  const daysInMonth = new Date(year, month + 1, 0).getDate();
  const prevMonthDays = new Date(year, month, 0).getDate();
  const totalCells = Math.ceil((firstDay + daysInMonth) / 7) * 7;

  let monthEventIds = new Set();
  let cellsHtml = "";

  for (let i = 0; i < totalCells; i++) {
    let cellYear = year;
    let cellMonth = month;
    let dayNum = 0;
    let isOtherMonth = false;

    if (i < firstDay) {
      dayNum = prevMonthDays - firstDay + i + 1;
      cellMonth = month - 1;
      if (cellMonth < 0) { cellMonth = 11; cellYear -= 1; }
      isOtherMonth = true;
    } else if (i >= firstDay + daysInMonth) {
      dayNum = i - (firstDay + daysInMonth) + 1;
      cellMonth = month + 1;
      if (cellMonth > 11) { cellMonth = 0; cellYear += 1; }
      isOtherMonth = true;
    } else {
      dayNum = i - firstDay + 1;
    }

    const isoDate = `${cellYear}-${String(cellMonth + 1).padStart(2, "0")}-${String(dayNum).padStart(2, "0")}`;
    const isToday = isoDate === todayIso;
    const dow = i % 7;
    const isWeekend = dow === 0 || dow === 6;
    const dayEvents = eventsByDate[isoDate] || [];
    if (!isOtherMonth) dayEvents.forEach(ev => monthEventIds.add(ev.id));

    const maxVisible = 3;
    const visibleEvents = dayEvents.slice(0, maxVisible);
    const hiddenCount = dayEvents.length - visibleEvents.length;

    const eventsHtml = visibleEvents.map(ev => {
      const col = getCalendarEventColorClass(ev);
      const doneClass = ev.status === "Completed" ? "is-done" : "";
      const timeLabel = ev.isMultiDay
        ? (ev.isFirstDay ? `${ev.start_time || "09:00"} · D1/${ev.totalDays}` : `Day ${ev.dayIndex}/${ev.totalDays}`)
        : (ev.start_time || "09:00");
      const partSummary = typeof formatEventParticipantsSummary === "function" ? formatEventParticipantsSummary(ev) : "";
      const tip = `${ev.title} (${ev.event_type || "Event"})\n${ev.start_date} ${ev.start_time || ""} – ${ev.end_date || ev.start_date} ${ev.end_time || ""}${partSummary ? `\nParticipants: ${partSummary}` : ""}`;
      return `
        <div class="cal-ev-pill ${col.cls} ${doneClass}" onclick="event.stopPropagation(); openScheduleModal(${ev.id})" title="${escapeHtml(tip)}">
          <span style="opacity:0.82; font-variant-numeric:tabular-nums;">${escapeHtml(timeLabel)}</span> ${escapeHtml(ev.title)}
        </div>
      `;
    }).join("");

    const moreHtml = hiddenCount > 0
      ? `<button type="button" class="cal-m-more-btn" onclick="event.stopPropagation(); jumpCalendarToDay('${isoDate}')">+${hiddenCount} more</button>`
      : "";

    cellsHtml += `
      <div class="cal-m-cell ${isOtherMonth ? "other-month" : ""} ${isWeekend ? "is-weekend" : ""} ${isToday ? "is-today" : ""}" onclick="openScheduleModalForDate('${isoDate}')" title="Click to add event on ${isoDate}">
        <div class="cal-m-cell-head">
          <button type="button" class="cal-m-day-btn" onclick="event.stopPropagation(); jumpCalendarToDay('${isoDate}')" title="Open Day View for ${isoDate}">${dayNum}</button>
          <span class="cal-m-add-hint admin-only">+</span>
        </div>
        ${eventsHtml}
        ${moreHtml}
      </div>
    `;
  }

  if (countBadge) countBadge.textContent = `${monthEventIds.size} event${monthEventIds.size === 1 ? "" : "s"} in ${SHORT_MONTH_NAMES[month]}`;

  stage.innerHTML = `
    <div class="cal-month-shell">
      <div class="cal-month-weekdays">
        ${WEEKDAY_NAMES_SHORT.map((d, idx) => `<div class="cal-month-weekday ${(idx === 0 || idx === 6) ? "is-weekend" : ""}">${d}</div>`).join("")}
      </div>
      <div id="monthly-calendar-grid" class="cal-month-grid">${cellsHtml}</div>
    </div>
  `;
}

function _buildHourlyColumnEventsHtml(dayEvents, isoDate, startHour, endHour, hourHeightPx) {
  const timed = dayEvents.filter(ev => !ev.isMultiDay);
  if (timed.length === 0) return "";

  const startMinBound = startHour * 60;
  const endMinBound = (endHour + 1) * 60;

  const normalized = timed.map(ev => {
    const sMin = Math.max(startMinBound, parseTimeToMinutes(ev.start_time, 9 * 60));
    let eMin = parseTimeToMinutes(ev.end_time, sMin + 60);
    if (eMin <= sMin) eMin = sMin + 45;
    eMin = Math.min(endMinBound, Math.max(sMin + 30, eMin));
    return { ev, sMin, eMin };
  }).sort((a, b) => a.sMin - b.sMin || b.eMin - a.eMin);

  // Simple overlap column placement
  const columns = [];
  normalized.forEach(item => {
    let placed = false;
    for (let c = 0; c < columns.length; c++) {
      const last = columns[c][columns[c].length - 1];
      if (last.eMin <= item.sMin) {
        columns[c].push(item);
        item.colIdx = c;
        placed = true;
        break;
      }
    }
    if (!placed) {
      item.colIdx = columns.length;
      columns.push([item]);
    }
  });
  const totalCols = Math.max(1, columns.length);

  return normalized.map(item => {
    const { ev, sMin, eMin, colIdx } = item;
    const topPx = ((sMin - startMinBound) / 60) * hourHeightPx;
    const heightPx = Math.max(24, ((eMin - sMin) / 60) * hourHeightPx - 2);
    const widthPct = 100 / totalCols;
    const leftPct = colIdx * widthPct;
    const col = getCalendarEventColorClass(ev);
    const doneClass = ev.status === "Completed" ? "is-done" : "";
    const partSummary = typeof formatEventParticipantsSummary === "function" ? formatEventParticipantsSummary(ev) : "";
    return `
      <div class="cal-tg-event-block cal-ev-pill ${col.cls} ${doneClass}"
           style="top:${topPx}px; height:${heightPx}px; left:calc(${leftPct}% + 2px); width:calc(${widthPct}% - 4px); white-space:normal;"
           onclick="event.stopPropagation(); openScheduleModal(${ev.id})"
           title="${escapeHtml(`${ev.title} (${ev.start_time || ""}–${ev.end_time || ""})`)}">
        <div style="font-weight:700; line-height:1.2; overflow:hidden; text-overflow:ellipsis;">${escapeHtml(ev.title)}</div>
        <div style="font-size:10px; opacity:0.85; margin-top:1px;">${escapeHtml(ev.start_time || "09:00")}–${escapeHtml(ev.end_time || "10:00")}${ev.instrument_or_location ? ` · ${escapeHtml(ev.instrument_or_location)}` : ""}</div>
        ${(heightPx >= 54 && partSummary) ? `<div style="font-size:10px; opacity:0.85; margin-top:2px;">Participants: ${escapeHtml(partSummary)}</div>` : ""}
      </div>
    `;
  }).join("");
}

function _renderCalendarWeekView(stage, titleEl, countBadge, focusDate, eventsByDate, todayIso) {
  const startOfWeek = new Date(focusDate.getFullYear(), focusDate.getMonth(), focusDate.getDate() - focusDate.getDay());
  const days = [];
  for (let i = 0; i < 7; i++) {
    const d = new Date(startOfWeek.getFullYear(), startOfWeek.getMonth(), startOfWeek.getDate() + i);
    days.push({ date: d, iso: formatIsoDateLocal(d), isToday: formatIsoDateLocal(d) === todayIso });
  }

  const first = days[0].date;
  const last = days[6].date;
  titleEl.textContent = first.getMonth() === last.getMonth()
    ? `${SHORT_MONTH_NAMES[first.getMonth()]} ${first.getDate()} – ${last.getDate()}, ${first.getFullYear()}`
    : `${SHORT_MONTH_NAMES[first.getMonth()]} ${first.getDate()} – ${SHORT_MONTH_NAMES[last.getMonth()]} ${last.getDate()}, ${last.getFullYear()}`;

  const weekEventIds = new Set();
  days.forEach(day => (eventsByDate[day.iso] || []).forEach(ev => weekEventIds.add(ev.id)));
  if (countBadge) countBadge.textContent = `${weekEventIds.size} event${weekEventIds.size === 1 ? "" : "s"} this week`;

  const startHour = 6;
  const endHour = 22;
  const hourHeightPx = 52;
  const nowMin = getKstCurrentMinutes();
  const nowTopPx = ((nowMin - startHour * 60) / 60) * hourHeightPx;
  const showNowLine = nowMin >= startHour * 60 && nowMin <= (endHour + 1) * 60;

  let hoursColHtml = "";
  for (let h = startHour; h <= endHour; h++) {
    hoursColHtml += `<div class="cal-tg-hour-label">${String(h).padStart(2, "0")}:00</div>`;
  }

  const allDayCellsHtml = days.map(day => {
    const multiEvs = (eventsByDate[day.iso] || []).filter(ev => ev.isMultiDay);
    return `
      <div class="cal-allday-cell">
        ${multiEvs.map(ev => {
          const col = getCalendarEventColorClass(ev);
          return `<div class="cal-ev-pill ${col.cls} ${ev.status === "Completed" ? "is-done" : ""}" onclick="event.stopPropagation(); openScheduleModal(${ev.id})" title="${escapeHtml(ev.title)}">${escapeHtml(ev.title)} (D${ev.dayIndex}/${ev.totalDays})</div>`;
        }).join("")}
      </div>
    `;
  }).join("");

  const dayColsHtml = days.map(day => {
    let slotsHtml = "";
    for (let h = startHour; h <= endHour; h++) {
      const sTime = `${String(h).padStart(2, "0")}:00`;
      const eTime = `${String(Math.min(23, h + 1)).padStart(2, "0")}:00`;
      slotsHtml += `<div class="cal-tg-slot" onclick="openScheduleModalForDate('${day.iso}', '${sTime}', '${eTime}')" title="Click to schedule ${day.iso} at ${sTime}"></div>`;
    }
    const evBlocksHtml = _buildHourlyColumnEventsHtml(eventsByDate[day.iso] || [], day.iso, startHour, endHour, hourHeightPx);
    const nowLineHtml = (day.isToday && showNowLine) ? `<div class="cal-tg-now-line" style="top:${nowTopPx}px;" title="Current KST Time"></div>` : "";
    return `
      <div class="cal-tg-day-col ${day.isToday ? "is-today" : ""}">
        ${slotsHtml}
        ${evBlocksHtml}
        ${nowLineHtml}
      </div>
    `;
  }).join("");

  stage.innerHTML = `
    <div class="cal-timegrid-wrap">
      <div class="cal-week-head-row">
        <div class="cal-tg-corner">GMT+9</div>
        ${days.map(day => `
          <div class="cal-tg-day-hdr ${day.isToday ? "is-today" : ""}" onclick="jumpCalendarToDay('${day.iso}')" title="Switch to Day View (${day.iso})">
            <div class="cal-tg-day-dow">${WEEKDAY_NAMES_SHORT[day.date.getDay()]}</div>
            <div class="cal-tg-day-num">${day.date.getDate()}</div>
          </div>
        `).join("")}
      </div>
      <div class="cal-allday-row mode-week">
        <div class="cal-tg-corner">Multi</div>
        ${allDayCellsHtml}
      </div>
      <div class="cal-tg-body mode-week" id="monthly-calendar-grid">
        <div class="cal-tg-hours-col">${hoursColHtml}</div>
        ${dayColsHtml}
      </div>
    </div>
  `;
}

function _renderCalendarDayView(stage, titleEl, countBadge, focusDate, focusIso, eventsByDate, todayIso) {
  const isToday = focusIso === todayIso;
  titleEl.textContent = `${WEEKDAY_NAMES_FULL[focusDate.getDay()]}, ${SHORT_MONTH_NAMES[focusDate.getMonth()]} ${focusDate.getDate()}, ${focusDate.getFullYear()}${isToday ? " (Today)" : ""}`;

  const dayEvents = eventsByDate[focusIso] || [];
  if (countBadge) countBadge.textContent = `${dayEvents.length} event${dayEvents.length === 1 ? "" : "s"} on ${focusIso}`;

  const startHour = 6;
  const endHour = 22;
  const hourHeightPx = 52;
  const nowMin = getKstCurrentMinutes();
  const nowTopPx = ((nowMin - startHour * 60) / 60) * hourHeightPx;
  const showNowLine = isToday && nowMin >= startHour * 60 && nowMin <= (endHour + 1) * 60;

  let hoursColHtml = "";
  let slotsHtml = "";
  for (let h = startHour; h <= endHour; h++) {
    const sTime = `${String(h).padStart(2, "0")}:00`;
    const eTime = `${String(Math.min(23, h + 1)).padStart(2, "0")}:00`;
    hoursColHtml += `<div class="cal-tg-hour-label">${sTime}</div>`;
    slotsHtml += `<div class="cal-tg-slot" onclick="openScheduleModalForDate('${focusIso}', '${sTime}', '${eTime}')" title="Click to schedule ${focusIso} at ${sTime}"></div>`;
  }

  const multiEvs = dayEvents.filter(ev => ev.isMultiDay);
  const evBlocksHtml = _buildHourlyColumnEventsHtml(dayEvents, focusIso, startHour, endHour, hourHeightPx);
  const nowLineHtml = showNowLine ? `<div class="cal-tg-now-line" style="top:${nowTopPx}px;"></div>` : "";

  // Mini Month Navigator for right sidebar
  const mYear = focusDate.getFullYear();
  const mMonth = focusDate.getMonth();
  const firstDow = new Date(mYear, mMonth, 1).getDay();
  const daysInMon = new Date(mYear, mMonth + 1, 0).getDate();
  const prevMonDays = new Date(mYear, mMonth, 0).getDate();
  const totalMini = Math.ceil((firstDow + daysInMon) / 7) * 7;
  let miniCells = WEEKDAY_NAMES_SHORT.map(d => `<div class="cal-mini-dow">${d[0]}</div>`).join("");
  for (let i = 0; i < totalMini; i++) {
    let cy = mYear, cm = mMonth, dn = 0, other = false;
    if (i < firstDow) {
      dn = prevMonDays - firstDow + i + 1; cm = mMonth - 1; if (cm < 0) { cm = 11; cy--; } other = true;
    } else if (i >= firstDow + daysInMon) {
      dn = i - (firstDow + daysInMon) + 1; cm = mMonth + 1; if (cm > 11) { cm = 0; cy++; } other = true;
    } else {
      dn = i - firstDow + 1;
    }
    const iso = `${cy}-${String(cm + 1).padStart(2, "0")}-${String(dn).padStart(2, "0")}`;
    const hasEv = (eventsByDate[iso] || []).length > 0;
    miniCells += `<button type="button" class="cal-mini-day ${other ? "other-month" : ""} ${iso === todayIso ? "is-today" : ""} ${iso === focusIso ? "is-selected" : ""} ${hasEv ? "has-ev" : ""}" onclick="jumpCalendarToDay('${iso}')">${dn}</button>`;
  }

  const sideSummaryHtml = dayEvents.length === 0
    ? `<div style="font-size:12px; color:#786354; padding:8px 0;">No events scheduled for this day. Click any time slot to schedule.</div>`
    : dayEvents.map(ev => {
        const col = getCalendarEventColorClass(ev);
        const partSummary = typeof formatEventParticipantsSummary === "function" ? formatEventParticipantsSummary(ev) : "";
        return `
          <div style="padding:7px 8px; background:#fffdf9; border:1px solid #e4d8c8; border-left:3px solid ${col.dot}; border-radius:6px; margin-bottom:6px; cursor:pointer;" onclick="openScheduleModal(${ev.id})">
            <div style="font-weight:700; font-size:12px; color:#2a1f18;">${escapeHtml(ev.title)}</div>
            <div style="font-size:11px; color:#786354; margin-top:2px;">${escapeHtml(ev.start_time || "09:00")}–${escapeHtml(ev.end_time || "10:00")} · ${escapeHtml(ev.event_type || "Event")}</div>
            ${partSummary ? `<div style="font-size:10.5px; color:#8c3d0c; margin-top:2px;">Participants: ${escapeHtml(partSummary)}</div>` : ""}
          </div>
        `;
      }).join("");

  stage.innerHTML = `
    <div class="cal-day-layout">
      <div class="cal-timegrid-wrap">
        <div class="cal-day-head-row">
          <div class="cal-tg-corner">GMT+9</div>
          <div class="cal-tg-day-hdr ${isToday ? "is-today" : ""}" style="text-align:left; padding:8px 12px; cursor:default;">
            <span style="font-weight:800; color:#2a1f18; font-size:13.5px;">${WEEKDAY_NAMES_FULL[focusDate.getDay()]}</span>
            <span style="font-size:12px; color:#786354; margin-left:8px;">${focusIso}</span>
          </div>
        </div>
        <div class="cal-allday-row mode-day">
          <div class="cal-tg-corner">Multi</div>
          <div class="cal-allday-cell">
            ${multiEvs.length === 0
              ? `<span style="font-size:11px; color:#9b8b7c; padding:2px 4px;">No multi-day events</span>`
              : multiEvs.map(ev => {
                  const col = getCalendarEventColorClass(ev);
                  return `<div class="cal-ev-pill ${col.cls}" onclick="openScheduleModal(${ev.id})">${escapeHtml(ev.title)} (Day ${ev.dayIndex}/${ev.totalDays})</div>`;
                }).join("")}
          </div>
        </div>
        <div class="cal-tg-body mode-day" id="monthly-calendar-grid">
          <div class="cal-tg-hours-col">${hoursColHtml}</div>
          <div class="cal-tg-day-col ${isToday ? "is-today" : ""}">
            ${slotsHtml}
            ${evBlocksHtml}
            ${nowLineHtml}
          </div>
        </div>
      </div>

      <div class="cal-mini-sidebar">
        <div class="cal-mini-box">
          <div style="display:flex; justify-content:space-between; align-items:center; font-size:12.5px; font-weight:800; color:#2a1f18;">
            <span>${MONTH_NAMES[mMonth]} ${mYear}</span>
            <button type="button" class="mp-btn-xs" onclick="setCalendarViewMode('month')">Month →</button>
          </div>
          <div class="cal-mini-grid">${miniCells}</div>
        </div>

        <div class="cal-mini-box">
          <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:8px;">
            <span style="font-size:12.5px; font-weight:800; color:#2a1f18;">Day Schedule (${dayEvents.length})</span>
            <button type="button" class="mp-btn-xs mp-btn-xs-teal admin-only" onclick="openScheduleModalForDate('${focusIso}')">+ Add</button>
          </div>
          ${sideSummaryHtml}
        </div>
      </div>
    </div>
  `;
}

function _renderCalendarAgendaView(stage, titleEl, countBadge, eventsByDate, todayIso) {
  const year = STATE.calendarYear;
  const month = STATE.calendarMonth;
  const monthPrefix = `${year}-${String(month + 1).padStart(2, "0")}-`;
  titleEl.textContent = `Agenda · ${MONTH_NAMES[month]} ${year}`;

  const matchingDates = Object.keys(eventsByDate)
    .filter(d => d.startsWith(monthPrefix) && eventsByDate[d].length > 0)
    .sort();

  const uniqIds = new Set();
  matchingDates.forEach(d => eventsByDate[d].forEach(ev => uniqIds.add(ev.id)));
  if (countBadge) countBadge.textContent = `${uniqIds.size} event${uniqIds.size === 1 ? "" : "s"} in ${SHORT_MONTH_NAMES[month]}`;

  if (matchingDates.length === 0) {
    stage.innerHTML = `
      <div id="monthly-calendar-grid" style="padding:36px 20px; text-align:center; color:#786354; border:1px dashed #d9bf9f; border-radius:8px; background:#faf6ef;">
        <div style="font-weight:700; color:#3d2b1f; margin-bottom:4px;">No events scheduled in ${MONTH_NAMES[month]} ${year}</div>
        <div style="font-size:12.5px;">Switch months or click <strong>+ Add Event</strong> to schedule a new lab session or meeting.</div>
      </div>
    `;
    return;
  }

  stage.innerHTML = `
    <div id="monthly-calendar-grid" class="cal-agenda-list">
      ${matchingDates.map(iso => {
        const dObj = parseIsoDateLocal(iso);
        const isToday = iso === todayIso;
        const evs = eventsByDate[iso];
        return `
          <div class="cal-agenda-day-group">
            <div class="cal-agenda-day-header ${isToday ? "is-today" : ""}">
              <span style="cursor:pointer;" onclick="jumpCalendarToDay('${iso}')">${WEEKDAY_NAMES_FULL[dObj.getDay()]}, ${SHORT_MONTH_NAMES[dObj.getMonth()]} ${dObj.getDate()}, ${dObj.getFullYear()} ${isToday ? `<span class="badge badge-amber" style="font-size:10px; margin-left:6px;">Today</span>` : ""}</span>
              <div style="display:flex; gap:6px; align-items:center;">
                <span style="font-size:11.5px; font-weight:600; color:#786354;">${evs.length} event${evs.length === 1 ? "" : "s"}</span>
                <button type="button" class="mp-btn-xs admin-only" onclick="openScheduleModalForDate('${iso}')">+ Add</button>
              </div>
            </div>
            ${evs.map(ev => {
              const col = getCalendarEventColorClass(ev);
              const partBadges = typeof renderEventParticipantsBadgesHtml === "function" ? renderEventParticipantsBadgesHtml(ev) : "";
              const timeStr = ev.isMultiDay ? `Day ${ev.dayIndex}/${ev.totalDays}` : `${ev.start_time || "09:00"} – ${ev.end_time || "10:00"}`;
              return `
                <div class="cal-agenda-row" onclick="openScheduleModal(${ev.id})">
                  <div class="cal-agenda-time" style="border-left:3px solid ${col.dot}; padding-left:8px;">${escapeHtml(timeStr)}</div>
                  <div style="flex:1; min-width:0;">
                    <div style="display:flex; align-items:center; gap:6px; flex-wrap:wrap;">
                      <strong style="color:#2a1f18; font-size:13px;">${escapeHtml(ev.title)}</strong>
                      <span class="badge badge-slate" style="font-size:10.5px;">${escapeHtml(ev.event_type || "Event")}</span>
                      <span class="badge ${ev.status === "Completed" ? "badge-green" : ev.status === "In Progress" ? "badge-amber" : "badge-blue"}" style="font-size:10.5px;">${escapeHtml(ev.status || "Scheduled")}</span>
                      ${partBadges}
                    </div>
                    ${(ev.instrument_or_location || ev.description) ? `<div style="font-size:12px; color:#5c493c; margin-top:3px;">${ev.instrument_or_location ? `📍 ${escapeHtml(ev.instrument_or_location)}` : ""}${ev.instrument_or_location && ev.description ? " · " : ""}${ev.description ? escapeHtml(ev.description.slice(0, 120)) : ""}</div>` : ""}
                  </div>
                  <button type="button" class="mp-btn-xs" onclick="event.stopPropagation(); pushSingleEventToGoogleCalendar(${ev.id})" title="Push to Google Calendar">+GCal</button>
                </div>
              `;
            }).join("")}
          </div>
        `;
      }).join("")}
    </div>
  `;
}

function openScheduleModalForDate(isoDate, startTime = null, endTime = null) {
  if (!requireAdminAuth()) return;
  openScheduleModal(null, isoDate, startTime, endTime);
}
window.openScheduleModalForDate = openScheduleModalForDate;

function buildGoogleCalendarTemplateUrl(item) {
  const sDateClean = (item.start_date || new Date().toISOString().split("T")[0]).replace(/-/g, "");
  const eDateClean = (item.end_date || item.start_date || sDateClean).replace(/-/g, "");
  const startClean = (item.start_time || "09:00").replace(":", "") + "00";
  const endClean = (item.end_time || "11:00").replace(":", "") + "00";
  const datesParam = `${sDateClean}T${startClean}/${eDateClean}T${endClean}`;

  const detailsParts = [];
  if (item.event_type) detailsParts.push(`Category: ${item.event_type}`);
  if (item.sample_id) detailsParts.push(`Sample/Batch: ${item.sample_id}`);
  if (item.end_date && item.end_date !== item.start_date) {
    detailsParts.push(`Multi-Day Schedule: ${item.start_date} -> ${item.end_date}`);
  }
  if (item.description) detailsParts.push(`Details: ${item.description}`);
  detailsParts.push("Synced from MatSci Nexus PhD Hub (Asia/Seoul • GMT+9)");

  const params = new URLSearchParams({
    action: "TEMPLATE",
    text: `[MatSci] ${item.title}`,
    dates: datesParam,
    details: detailsParts.join("\n"),
    location: item.instrument_or_location || "SKKU Materials Science Lab",
    ctz: "Asia/Seoul",
    authuser: OWNER_GOOGLE_EMAIL
  });
  return `https://calendar.google.com/calendar/render?${params.toString()}`;
}
function pushSingleEventToGoogleCalendar(id) {
  const item = STATE.schedule.find(x => x.id === id);
  if (!item) return;
  const url = buildGoogleCalendarTemplateUrl(item);
  window.open(url, "_blank");
  showToast(`Opened Google Calendar (${OWNER_GOOGLE_EMAIL}) to save event!`);
}

function exportScheduleToIcs() {
  if (!STATE.schedule || STATE.schedule.length === 0) {
    showToast("No events to export.", "warn");
    return;
  }

  const lines = [
    "BEGIN:VCALENDAR",
    "VERSION:2.0",
    "PRODID:-//MatSci Nexus//PhD Research Hub//EN",
    "CALSCALE:GREGORIAN",
    "METHOD:PUBLISH",
    `X-WR-CALNAME:MatSci Research Schedule (${OWNER_GOOGLE_EMAIL})`,
    "X-WR-TIMEZONE:Asia/Seoul"
  ];

  STATE.schedule.forEach(ev => {
    const sd = (ev.start_date || "2026-11-11").replace(/-/g, "");
    const ed = (ev.end_date || ev.start_date || sd).replace(/-/g, "");
    const st = (ev.start_time || "09:00").replace(":", "") + "00";
    const et = (ev.end_time || "11:00").replace(":", "") + "00";
    const desc = `${ev.event_type || ""} | Sample: ${ev.sample_id || "N/A"} | ${ev.description || ""}`.replace(/\r?\n/g, "\\n");

    lines.push("BEGIN:VEVENT");
    lines.push(`UID:matsci-${ev.id}@lamvt.skku`);
    lines.push(`DTSTART:${sd}T${st}`);
    lines.push(`DTEND:${ed}T${et}`);
    lines.push(`SUMMARY:[MatSci] ${ev.title}`);
    lines.push(`LOCATION:${ev.instrument_or_location || "SKKU Lab"}`);
    lines.push(`DESCRIPTION:${desc}`);
    lines.push("END:VEVENT");
  });

  lines.push("END:VCALENDAR");
  const blob = new Blob([lines.join("\r\n")], { type: "text/calendar;charset=utf-8" });
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = "MatSci_Schedule_lamvt_skku.ics";
  document.body.appendChild(a);
  a.click();
  a.remove();
  URL.revokeObjectURL(url);
  showToast(`Downloaded .ics file! Import it into Google Calendar (${OWNER_GOOGLE_EMAIL}) Settings -> Import.`);
}
