let _cloudPushTimer = null;

function saveStaticDb(options = {}) {
  const skipCloudPush = Boolean(options && options.skipCloudPush);
  const activePersonalEmail = getActivePersonalWorkspaceEmail();
  if (activePersonalEmail && STATE.usersRegistry && STATE.usersRegistry[activePersonalEmail]) {
    const u = STATE.usersRegistry[activePersonalEmail];
    const userFolder = getPersonalUserFolderName(u);
    u.workspace = {
      ...(u.workspace || {}),
      papers: (STATE.papers || []).filter(p => !p._sharedFromAdmin && !p._fromUserEmail).map(p => ({
        ...p,
        project_folder: userFolder,
        visibility: "Private",
        allowed_users: [],
        owner_email: activePersonalEmail,
        owner_name: u.name || activePersonalEmail
      })),
      structures: (STATE.structures || []).filter(s => !s._sharedFromAdmin && !s._fromUserEmail).map(s => ({
        ...s,
        project_folder: (s.project_folder && typeof s.project_folder === "string" && s.project_folder.trim() && !isPersonalUserFolderName(s.project_folder))
          ? s.project_folder.trim()
          : "General Research",
        visibility: "Private",
        allowed_users: [],
        owner_email: activePersonalEmail,
        owner_name: u.name || activePersonalEmail
      })),
      schedule: (STATE.schedule || []).filter(ev => !ev._sharedFromAdmin && !ev._fromUserEmail),
      expReportRows: STATE.expReportRows || [],
      litReportRows: STATE.litReportRows || []
    };
    u.lastUpdatedAt = getGmt9NowStr();
    u.updatedAtMs = Date.now();
    persistUsersRegistryLocal();
  } else if (STATE.auth && STATE.auth.isAdmin && !STATE.adminPreviewUserEmail) {
    // Separate Admin Master items from User-Uploaded Private items (never leak user uploads into masterData!)
    STATE.masterData = {
      papers: (STATE.papers || []).filter(p => !p._fromUserEmail),
      structures: (STATE.structures || []).filter(s => !s._fromUserEmail),
      schedule: (STATE.schedule || []).filter(ev => !ev._fromUserEmail),
      profile: STATE.profile || {}
    };

    // Sync any Admin edits/deletions to user-owned structures/papers cleanly back to their user workspace
    if (!options.skipUserWorkspaceSync && STATE._adminMergedUserEmails && STATE.usersRegistry && typeof STATE.usersRegistry === "object") {
      let usersModified = false;
      Object.keys(STATE.usersRegistry).forEach(email => {
        const u = STATE.usersRegistry[email];
        if (!u || !u.workspace) return;
        const normEmail = normalizeEmail(email);
        if (!STATE._adminMergedUserEmails.has(normEmail)) return;
        const userFolder = getPersonalUserFolderName(u);
        const liveUserStructs = (STATE.structures || [])
          .filter(s => s._fromUserEmail === normEmail)
          .map(s => {
            const copy = { ...s };
            const restoredFolder = (copy._originalUserFolder && typeof copy._originalUserFolder === "string" && copy._originalUserFolder.trim() && !isPersonalUserFolderName(copy._originalUserFolder))
              ? copy._originalUserFolder.trim()
              : "General Research";
            delete copy._fromUserEmail;
            delete copy._fromUserName;
            delete copy._originalUserFolder;
            copy.project_folder = restoredFolder;
            copy.visibility = "Private";
            copy.allowed_users = [];
            copy.owner_email = normEmail;
            copy.owner_name = u.name || normEmail;
            return copy;
          });
        const liveUserPapers = (STATE.papers || [])
          .filter(p => p._fromUserEmail === normEmail)
          .map(p => {
            const copy = { ...p };
            delete copy._fromUserEmail;
            delete copy._fromUserName;
            copy.project_folder = userFolder;
            copy.visibility = "Private";
            copy.allowed_users = [];
            copy.owner_email = normEmail;
            copy.owner_name = u.name || normEmail;
            return copy;
          });
        if (JSON.stringify(u.workspace.structures || []) !== JSON.stringify(liveUserStructs)) {
          u.workspace.structures = liveUserStructs;
          u.updatedAtMs = Date.now();
          u.lastUpdatedAt = getGmt9NowStr();
          usersModified = true;
        }
        if (JSON.stringify(u.workspace.papers || []) !== JSON.stringify(liveUserPapers)) {
          u.workspace.papers = liveUserPapers;
          u.updatedAtMs = Date.now();
          u.lastUpdatedAt = getGmt9NowStr();
          usersModified = true;
        }
      });
      if (usersModified) persistUsersRegistryLocal();
    }
  } else if (!STATE.masterData) {
    STATE.masterData = {
      papers: (STATE.papers || []).filter(p => !p._fromUserEmail),
      structures: (STATE.structures || []).filter(s => !s._fromUserEmail),
      schedule: (STATE.schedule || []).filter(ev => !ev._fromUserEmail),
      profile: STATE.profile || {}
    };
  }

  if (STATE.masterData) {
    STATE.masterData.profile = STATE.profile || STATE.masterData.profile || {};
  }

  // Reconcile canonical global Structure IDs right before persisting locally & syncing to cloud
  if (typeof ensureAllStructuralIdsGlobal === "function") {
    ensureAllStructuralIdsGlobal();
  }

  const nowIso = new Date().toISOString();
  const isStrictAdminSave = Boolean(STATE.auth && STATE.auth.isAdmin && !STATE.adminPreviewUserEmail);
  let masterUpdatedAt = options.cloudMasterTimestamp || null;
  if (!masterUpdatedAt) {
    if (isStrictAdminSave && !options.preserveMasterTimestamp) {
      masterUpdatedAt = nowIso;
    } else {
      try {
        const prevRaw = localStorage.getItem("matsci_static_db_v4");
        const prevParsed = prevRaw ? JSON.parse(prevRaw) : null;
        masterUpdatedAt = (prevParsed && (prevParsed.master_updated_at || prevParsed.updated_at)) || "1970-01-01T00:00:00.000Z";
      } catch (e) {
        masterUpdatedAt = "1970-01-01T00:00:00.000Z";
      }
    }
  }

  localStorage.setItem("matsci_static_db_v4", JSON.stringify({
    papers: (STATE.masterData && STATE.masterData.papers) || STATE.papers,
    structures: (STATE.masterData && STATE.masterData.structures) || STATE.structures,
    schedule: (STATE.masterData && STATE.masterData.schedule) || STATE.schedule,
    profile: (STATE.masterData && STATE.masterData.profile) || STATE.profile,
    users_registry: STATE.usersRegistry || {},
    user_groups: STATE.userGroups || {},
    deleted_users: Array.from(getDeletedUsersSet()),
    deleted_users_map: getDeletedUsersMap(),
    deleted_groups: Array.from(getDeletedGroupsSet()),
    deleted_structures: Object.keys(getDeletedStructuresMap()),
    deleted_structures_map: getDeletedStructuresMap(),
    deleted_papers: Object.keys(getDeletedPapersMap()),
    deleted_papers_map: getDeletedPapersMap(),
    deleted_schedule: Object.keys(getDeletedScheduleMap()),
    deleted_schedule_map: getDeletedScheduleMap(),
    master_updated_at: masterUpdatedAt,
    updated_at: nowIso
  }));

  renderDashboardAdminUsersSummary();

  if (!skipCloudPush) {
    if (_cloudPushTimer) clearTimeout(_cloudPushTimer);
    _cloudPushTimer = setTimeout(() => {
      syncDatabaseToCloudInstant("Auto-Sync Workspace Update", true);
    }, 600);
  }
}

function exportDataJson() {
  const sanitizedExportUsers = {};
  Object.entries(STATE.usersRegistry || {}).forEach(([k, u]) => {
    if (u && typeof u === "object") {
      const uCopy = { ...u };
      if (uCopy.passwordPlainHint) uCopy.passwordPlainHint = "••••••••";
      sanitizedExportUsers[k] = uCopy;
    }
  });

  purgeAllTombstonedEntities();
  const exportObj = {
    version: "4.0",
    exported_at: new Date().toISOString(),
    profile: (STATE.masterData && STATE.masterData.profile) || STATE.profile,
    papers: ((STATE.masterData && STATE.masterData.papers) || STATE.papers || []).filter(p => !isPaperTombstoned(p.id, p.doi)),
    structures: ((STATE.masterData && STATE.masterData.structures) || STATE.structures || []).filter(s => !isStructureTombstoned(s.id, s.structural_id)),
    schedule: ((STATE.masterData && STATE.masterData.schedule) || STATE.schedule || []).filter(ev => !isScheduleTombstoned(ev.id)),
    event_categories: ensureEventCategoriesInitialized(),
    users_registry: sanitizedExportUsers,
    user_groups: STATE.userGroups || {},
    deleted_users: Array.from(getDeletedUsersSet()),
    deleted_users_map: getDeletedUsersMap(),
    deleted_groups: Array.from(getDeletedGroupsSet()),
    deleted_structures: Object.keys(getDeletedStructuresMap()),
    deleted_structures_map: getDeletedStructuresMap(),
    deleted_papers: Object.keys(getDeletedPapersMap()),
    deleted_papers_map: getDeletedPapersMap(),
    deleted_schedule: Object.keys(getDeletedScheduleMap()),
    deleted_schedule_map: getDeletedScheduleMap()
  };
  const jsonStr = JSON.stringify(exportObj, null, 2);
  const blob = new Blob([jsonStr], { type: "application/json" });
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = "data.json";
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  URL.revokeObjectURL(url);
  showToast("💾 data.json downloaded! Drag and drop into GitHub frontend/ folder to sync to all computers.", "success");
}

async function commitDataJsonToGitHub(options = {}) {
  const silent = !!(options && options.silent);
  let token = localStorage.getItem("matsci_github_token") || getBuiltInCloudToken() || "";
  if (!token) {
    const inputToken = prompt(
      "Enter your GitHub Personal Access Token (with 'repo' scope or fine-grained 'Contents: Read & Write'):\n\n" +
      "Once configured, all database updates and Academic CV changes will automatically sync to GitHub Cloud with 1 click!"
    );
    if (!inputToken || !inputToken.trim()) {
      if (!silent) exportDataJson();
      return;
    }
    token = inputToken.trim();
    localStorage.setItem("matsci_github_token", token);
  }

  if (!silent) {
    showToast("Syncing data.json directly to GitHub repository...", "info");
  }
  try {
    const repo = "tienlamvu/lamreseach";
    const path = "frontend/data.json";

    let sha = "";
    try {
      const getRes = await fetch(`https://api.github.com/repos/${repo}/contents/${path}?v=${Date.now()}`, {
        headers: {
          "Authorization": `Bearer ${token}`,
          "Accept": "application/vnd.github.v3+json"
        }
      });
      if (getRes.ok) {
        const fileData = await getRes.json();
        sha = fileData.sha;
      }
    } catch (e) {
      console.warn("Could not get existing file sha:", e);
    }

    purgeAllTombstonedEntities();
    const exportObj = {
      version: "4.0",
      exported_at: new Date().toISOString(),
      profile: (STATE.masterData && STATE.masterData.profile) || STATE.profile,
      papers: ((STATE.masterData && STATE.masterData.papers) || STATE.papers || []).filter(p => !isPaperTombstoned(p.id, p.doi)),
      structures: ((STATE.masterData && STATE.masterData.structures) || STATE.structures || []).filter(s => !isStructureTombstoned(s.id, s.structural_id)),
      schedule: ((STATE.masterData && STATE.masterData.schedule) || STATE.schedule || []).filter(ev => !isScheduleTombstoned(ev.id)),
      event_categories: ensureEventCategoriesInitialized(),
      users_registry: STATE.usersRegistry || {},
      user_groups: STATE.userGroups || {},
      deleted_users: Array.from(getDeletedUsersSet()),
      deleted_users_map: getDeletedUsersMap(),
      deleted_groups: Array.from(getDeletedGroupsSet()),
      deleted_structures: Object.keys(getDeletedStructuresMap()),
      deleted_structures_map: getDeletedStructuresMap(),
      deleted_papers: Object.keys(getDeletedPapersMap()),
      deleted_papers_map: getDeletedPapersMap(),
      deleted_schedule: Object.keys(getDeletedScheduleMap()),
      deleted_schedule_map: getDeletedScheduleMap()
    };

    const contentUtf8 = JSON.stringify(exportObj, null, 2);
    const bytes = new TextEncoder().encode(contentUtf8);
    let binary = "";
    for (let i = 0; i < bytes.byteLength; i++) {
      binary += String.fromCharCode(bytes[i]);
    }
    const base64Content = btoa(binary);

    const putRes = await fetch(`https://api.github.com/repos/${repo}/contents/${path}`, {
      method: "PUT",
      headers: {
        "Authorization": `Bearer ${token}`,
        "Accept": "application/vnd.github.v3+json",
        "Content-Type": "application/json"
      },
      body: JSON.stringify({
        message: `Direct Cloud Sync: Updated research data & CV [${new Date().toLocaleString()}]`,
        content: base64Content,
        sha: sha || undefined
      })
    });

    if (!putRes.ok) {
      const errData = await putRes.json();
      if (putRes.status === 401 || putRes.status === 403) {
        localStorage.removeItem("matsci_github_token");
        throw new Error("Invalid or expired GitHub Token. Please re-enter.");
      }
      throw new Error(errData.message || `GitHub API HTTP Error ${putRes.status}`);
    }

    // Also sync root data.json
    try {
      let rootSha = "";
      const rootGet = await fetch(`https://api.github.com/repos/${repo}/contents/data.json?v=${Date.now()}`, {
        headers: {
          "Authorization": `Bearer ${token}`,
          "Accept": "application/vnd.github.v3+json"
        }
      });
      if (rootGet.ok) {
        const rootData = await rootGet.json();
        rootSha = rootData.sha;
      }
      await fetch(`https://api.github.com/repos/${repo}/contents/data.json`, {
        method: "PUT",
        headers: {
          "Authorization": `Bearer ${token}`,
          "Accept": "application/vnd.github.v3+json",
          "Content-Type": "application/json"
        },
        body: JSON.stringify({
          message: `Direct Cloud Sync: Updated root data.json [${new Date().toLocaleString()}]`,
          content: base64Content,
          sha: rootSha || undefined
        })
      });
    } catch (e) {
      console.warn("Could not sync root data.json:", e);
    }

    try {
      const prevRaw = localStorage.getItem("matsci_static_db_v4");
      const prevObj = prevRaw ? JSON.parse(prevRaw) : {};
      prevObj.master_updated_at = exportObj.exported_at;
      prevObj.updated_at = exportObj.exported_at;
      prevObj.structures = exportObj.structures;
      prevObj.papers = exportObj.papers;
      prevObj.schedule = exportObj.schedule;
      prevObj.deleted_structures = exportObj.deleted_structures;
      prevObj.deleted_structures_map = exportObj.deleted_structures_map;
      localStorage.setItem("matsci_static_db_v4", JSON.stringify(prevObj));
    } catch (e) {}

    if (!silent) {
      showToast("🎉 Successfully synced directly to GitHub! Changes will appear live across all devices in ~1 minute.", "success");
    } else {
      showToast("☁️ Auto-synced changes to GitHub Cloud!", "success");
    }
  } catch (err) {
    console.error("GitHub Sync error:", err);
    if (!silent) {
      showToast(`GitHub Sync error: ${err.message}. Downloading data.json fallback...`, "error");
      exportDataJson();
    }
  }
}

function syncOrExportDataJson() {
  if (confirm("Choose data synchronization method:\n\n- Click OK: 1-Click Direct Cloud Sync to GitHub via Personal Access Token\n- Click Cancel: Download data.json to upload manually")) {
    commitDataJsonToGitHub();
  } else {
    exportDataJson();
  }
}

